comms.text:
@1 וּשְׁלַח יַעֲקֹב אִזְגַּדִּין קֳדָמוֹהִי לְוַת עֵשָׂו אֲחוּהִי לְאַרְעָא דְשֵׂעִיר לַחֲקַל דְאֱדוֹם:
@2 וּפַקִּיד יָתְהוֹן לְמֵימָר כְּדֵין תֵּימְרוּן לְרִבּוֹנִי לְעֵשָׂו כִּדְנַן אֲמַר עַבְדָּךְ יַעֲקֹב עִם לָבָן דָּרִית וְאוֹחָרִית עַד כְּעָן:
@3 וַהֲוָה לִי תּוֹרִין וַחֲמָרִין עָאן וְעַבְדִּין וְאַמְהָן וּשְׁלָחִית לְחַוָּאָה לְרִבּוֹנִי לְאַשְׁכָּחָא רַחֲמִין בְּעֵינָךְ:
@4 וְתָבוּ אִזְגַּדַּיָּא לְוַת יַעֲקֹב לְמֵימָר אֲתֵינָא לְוַת אָחוּךְ לְוַת עֵשָׂו וְאַף אָתֵי לְקַדָּמוּתָךְ וְאַרְבַּע מְאָה גַּבְרָא עִמֵּהּ:
@5 וּדְחִיל יַעֲקֹב לַחֲדָא וַעֲקַת לֵהּ וּפַלִּיג יָת עַמָּא דִּי עִמֵּהּ וְיָת עָנָא וְיָת תּוֹרֵי וְגַמְלַיָּא לִ:תרֵין מַשִּׁירְיָן:
@6 וַאֲמַר אִם יֵיתֵי עֵשָׂו לְמַשְׁרִיתָא חֲדָא וְיִמְחִנֵּהּ וִיהֵי (נ''י וְיִמְחֵנַּהּ וּתְהִי) מַשְׁרִיתָא דְאִשְׁתָּאַר לְשֵׁיזָבָא:
@7 וַאֲמַר יַעֲקֹב אֱלָהֵהּ דְּאַבָּא אַבְרָהָם וֵאֱלָהֵהּ דְּאַבָּא יִצְחָק יְיָ דִּי אֲמַר לִי תּוּב לְאַרְעָךְ וּלְיַלָּדוּתָךְ וְאוֹטֵיב עִמָּךְ:
@8 זְעִירָן זָכוּתַי מִכֹּל חִסְדִּן וּמִכָּל טַבְוָן דִּי עֲבַדְתָּ עִם עַבְדָּךְ אֲרֵי יְחִידִי עֲבָרִית יָת יַרְדְּנָא הָדֵין וּכְעַן הֲוֵיתִי לִתְרֵין (נ''י לְתַרְתֵּין) מַשִּׁרְיָן:
@9 שֵׁזַבְנִי כְעַן מִידָא דְאָחִי מִידָא דְעֵשָׁו אֲרֵי דַחֵל אֲנָא מִנֵּהּ דִּילְמָא יֵיתֵי וְיִמְחִנַּנִי אִמָּא עַל בְּנַיָּא:
@10 וְאַתְּ אֲמַרְתָּ אוֹטָבָא אוֹטִיב עִמָּךְ וֶאֱשַׁוֵּי יָת בְּנָיךְ סַגִּיאִין כְּחַלָּא דְיַמָּא דִּי לָא יִתִּמְנוּן מִסַּגִּי:
@11 וּבָת תַּמָּן בְּלֵילְיָא הַהוּא וּנְסִיב מִן דְּאַיְתִי בִּידֵהּ תִּקְרֻבְתָּא לְעֵשָׂו אֲחוּהִי:
@12 עִזֵּי מָאתָן וּתְיָשַׁיָא עֶסְרִין רְחֵלִין מָאתָן וְדִכְרִין עֶסְרִין:
@13 גַּמְלֵי מֶנְקָתָא וּבְנֵיהוֹן תְּלָתִין תּוֹרְתָא אַרְבְּעִין וְתוֹרֵי עַסְרָא אַתְנָן עֶסְרִין וְעִירֵי עַסְרָא:
@14 וִיהַב בְּיַד עַבְדּוֹהִי עֶדְרָא עֶדְרָא בִּלְחוֹדוֹהִי וַאֲמַר לְעַבְדּוֹהִי עִבָּרוּ קֳדָמַי וּרְוָחָא תְּשַׁווּן בֵּין עֶדְרָא וּבֵין עֶדְרָא:
@15 וּפַקִד יָת קַדְמָאָה לְמֵימָר אֲרֵי יְעַרְעִנָּךְ עֵשָׂו אָחִי וּשְׁאֵלִנָּךְ לְמֵימָר לְמָן אַתְּ וּלְאָן אַתְּ אָזֵל וּלְמָן אִלֵּין דִּקֳדָמָךְ:
@16 וְתֵימַר לְעַבְדָךְ לְיַעֲקֹב תִּקְרֻבְתָּא הִיא דִמְשַׁלְּחָא לְרִבּוֹנִי לְעֵשָׂו וְהָא אַף הוּא אָתֵי בַתְרָנָא:
@17 וּפַקִּיד אַף יָת תִּנְיָנָא אַף יָת תְּלִיתָאָה אַף יָת כָּל דְּאָזְלִין בָּתַר עֲדָרַיָּא לְמֵימָר כְּפִתְגָּמָא הָדֵין תְּמַלְּלוּן עִם עֵשָׂו כַּד תַּשְׁכְּחוּן יָתֵהּ:
@18 וְתֵימְרוּן אַף הָא עַבְדָּךְ יַעֲקֹב אָתֵי בַתְרָנָא אֲרֵי אֲמַר אַנְחִנֵּהּ לְרוּגְזֵהּ בְּתִקְרֻבְתָּא דְּאָזְלַת קֳדָמַי וּבָתַר כֵּן אֶחֱזֵי אַפּוֹהִי מָאִים יִסַּב אַפָּי:
@19 וַעֲבָרַת תִּקְרֻבְתָּא עַל אַפּוֹהִי וְהוּא בָת בְּלֵילְיָא הַהוּא בְּמַשְׁרִיתָא:
@20 וְקָם בְּלֵילְיָא הוּא וּדְבַר יָת תַּרְתֵּין נְשׁוֹהִי וְיָת תַּרְתֵּין לְחֵינָתֵהּ וְיָת חַד עֲסַר בְּנוֹהִי וַעֲבַר יָת מַעֲבַר יוּבְקָא:
@21 וּדְבָרִנּוּן וְעַבָּרִנּוּן יָת נַחְלָא וְאַעְבַּר יָת דִּילֵהּ:
@22 וְאִשְׁתָּאַר יַעֲקֹב בִּלְחוֹדוֹהִי וְאִשְׁתַּדֵּל גַּבְרָא עִמֵּהּ עַד דִּסְלֵק צַפְרָא:
@23 וַחֲזָא אֲרֵי לָא יָכִיל לֵהּ וּקְרֵב בִּפְתֵי יַרְכֵּהּ וְזָע פְּתֵי יַרְכָּא דְיַעֲקֹב בְּאִשְׁתַּדָּלוּתֵהּ עִמֵּהּ:
@24 וַאֲמַר שַׁלְּחַנִּי אֲרֵי סְלִיק צַפְרָא וַאֲמַר לָא אֲשַׁלְחִנָךְ אֶלָּהֵין בֵּרַכְתָּנִי:
@25 וַאֲמַר לֵהּ מָה שְׁמָךְ וַאֲמַר יַעֲקֹב:
@26 וַאֲמַר לָא יַעֲקֹב יִתְאֲמַר עוֹד שְׁמָךְ אֶלָּהֵין יִשְׂרָאֵל אֲרֵי רַבְרְבַת קֳדָם יְיָ וְעִם גּוּבְרַיָּא וִיכָלְתָּא:
@27 וּשְׁאֵל יַעֲקֹב וַאֲמַר חַוִּי כְעַן שְׁמָךְ וַאֲמַר לְמָה דְנַן אַתְּ שָׁאֵל לִשְׁמִי וּבָרִיךְ יָתֵהּ תַּמָּן:
@28 וּקְרָא יַעֲקֹב שְׁמָא דְאַתְרָא פְּנִיאֵל אֲרֵי חֲזֵיתִי מַלְאָכַיָּא דַּיְיָ אַפִּין בְּאַפִּין וְאִשְׁתְּזָבַת נַפְשִׁי:
@29 וּדְנַח לֵהּ שִׁמְשָׁא כְּמָא דִּי עֲבַר יָת פְּנוּאֵל וְהוּא מַטְלַע עַל יַרְכֵּהּ:
@30 עַל כֵן לָא יֵיכְלוּן בְּנֵי יִשְׂרָאֵל יָת גִּידָא דְנַשְׁיָא דִּי עַל פְּתֵי יַרְכָּא עַד יוֹמָא הָדֵין אֲרֵי קְרֵיב בִּפְתֵי יַרְכָּא דְיַעֲקֹב בְּגִידָא דְנַשְׁיָא:
@31 וּזְקַף יַעֲקֹב עֵינוֹהִי וַחֲזָא וְהָא עֵשָׂו אֲתָא וְעִמֵּהּ אַרְבַּע מְאָה גֻּבְרִין וּפַלִּיג יָת בְּנַיָּא עַל לֵאָה וְעַל רָחֵל וְעַל תַּרְתֵּין לְחֵינָתָא:
@32 וְשַׁוִּי יָת לְחֵינָתָא וְיָת בְּנֵיהֶן קַדְמָאִין וְיָת לֵאָה וּבְנָהָא בַּתְרָאִין וְיָת רָחֵל וְיָת יוֹסֵף בַּתְרָאִין:
@33 וְהוּא עֲבַר קֳדָמֵיהוֹן וּסְגִיד עַל אַרְעָא שְׁבַע זִמְנִין עַד מִקְרְבֵהּ עַד (נ''י לְוַת) אֲחוּהִי:
@34 וּרְהַט עֵשָׂו לְקַדָּמוּתֵהּ וְגַפְּפֵהּ וּנְפַל עַל צַוְּארֵהּ וְנַשְׁקֵהּ וּבְכוֹ:
@35 וּזְקַף יָת עֵינוֹהִי וַחֲזָא יָת נְשַׁיָּא וְיָת בְּנַיָּא וַאֲמַר מָן אִלֵּין לָךְ וַאֲמַר בְּנַיָּא דִּי חַן יְיָ יָת עַבְדָּךְ:
@36 וּקְרִיבָן לְחֵינָתָא אִנוּן וּבְנֵיהֶן וּסְגִידוּ:
@37 וּקְרִיבָא אַף לֵאָה וּבְנָהָא וּסְגִידוּ וּבָתַר כֵּן קְרֵיב יוֹסֵף וְרָחֵל וּסְגִידוּ:
@38 וַאֲמַר מָן לָךְ כָּל מַשְׁרִיתָא הָדֵין דִּי עֲרָעִית וַאֲמַר לְאַשְׁכָּחָא רַחֲמִין בְּעֵינֵי רִבּוֹנִי:
@39 וַאֲמַר עֵשָׂו אִית לִי סַגִּי אָחִי אַצְלַח בְּדִילָךְ:
@40 וַאֲמַר יַעֲקֹב בְּבָעוּ אִם כְּעַן אַשְׁכָּחִית רַחֲמִין בְּעֵינָיךְ וּתְקַבֵּל תִּקְרֻבְתִּי מִן יְדִי אֲרֵי עַל כֵּן חֲזִתִּנּוּן לְאַפָּיךְ כְּחֵיזוּ אַפֵּי רַבְרְבַיָּא וְאִתְרְעֵית לִי:
@41 קַבֵּל כְּעַן יָת תִּקְרֻבְתִּי דְּאִתּוֹתִיאַת לָךְ אֲרֵי רַחִים עֲלַי (קֳדָם) יְיָ וַאֲרֵי אִית לִי כֹלָּא וְאַתְקֵף בֵּהּ וְקַבִּיל:
@42 וַאֲמַר נִטַל וְנֵהָךְ וְאֵיהַךְ לְקָבְלָךְ:
@43 וַאֲמַר לֵהּ רִבּוֹנִי יְדַע אֲרֵי יָנְקַיָּא רַכִּיכִין וְעָנָא וְתוֹרֵי מֵינִקְתָּא עָלָי וּדְחוֹקִנּוּן יוֹמָא חַד וִימוּתוּן כָּל עָנָא:
@44 יְעִבַּר כְּעַן רִבּוֹנִי קֳדָם עַבְדֵּהּ וַאֲנָא אֱדַבֵּר בְּנִיחַ לְרֶגֶל עוֹבַדְתָּא דִּי קֳדָמַי וּלְרֶגֶל יָנְקַיָּא עַד דִּי אֵעוֹל לְוַת רִבּוֹנִי לְשֵׂעִיר:
@45 וַאֲמַר עֵשָׂו אֶשְׁבּוֹק כְּעַן עִמָּךְ מִן עַמָּא דְּעִמִּי וַאֲמַר לְמָא דְנַן אַשְׁכַּח רַחֲמִין בְּעֵינֵי רִבּוֹנִי:
@46 וְתַב בְּיוֹמָא הַהוּא עֵשָׂו לְאָרְחֵהּ לְשֵׂעִיר:
@47 וְיַעֲקֹב נְטַל לְסֻכּוֹת וּבְנָא לֵהּ בֵּיתָא וְלִבְעִירֵהּ עֲבַד מְטַלָּן עַל כֵּן קְרָא שְׁמָא דְאַתְרָא סֻכּוֹת:
@48 וַאֲתָא יַעֲקֹב שְׁלִים קַרְתָּא דִּשְׁכֶם דִּי בְּאַרְעָא דִּכְנָעַן בְּמֵיתֵהּ מִפַּדַּן דַּאֲרָם וּשְׁרָא לָקֳבֵל (אַפֵּי) קַרְתָּא:
@49 וּזְבַן יָת אַחֲסָנַת חַקְלָא דִּי פְרַס תַּמָּן מַשְׁכְּנֵהּ מִידָא דִּבְנֵי חֲמוֹר אֲבוּהִי דִּשְׁכֶם בְּמֵאָה חוּרְפָן:
@50 וַאֲקֵם תַּמָּן מַדְבְּחָא וּפְלַח עֲלוֹהִי קֳדָם אֵל אֱלָהָא דְיִשְׂרָאֵל:
@51 וּנְפָקַת דִּינָה בַּת לֵאָה דִּי יְלִידַת לְיַעֲקֹב לְמֶחֱזֵי בִּבְנַת אַרְעָא:
@52 וַחֲזָא יָתַהּ שְׁכֶם בַּר חֲמוֹר חִוָאָה רַבָּא דְאַרְעָא וּדְבַר יָתַהּ וּשְׁכִיב יָתַהּ וְעַנְיַהּ:
@53 וְאִתְרְעִיאַת נַפְשֵׁהּ בְּדִינָה בַּת יַעֲקֹב וּרְחֵים יָת עוּלֶמְתָּא וּמַלִּיל עַל לִבָּא דְעוּלֶמְתָּא:
@54 וַאֲמַר שְׁכֶם לַחֲמוֹר אֲבוּהִי לְמֵימָר סַב לִי יָת עוּלֶמְתָּא הָדָא לְאִנְתּוּ:
@55 וְיַעֲקֹב שְׁמַע אֲרֵי סָאֵיב יָת דִּינָה בְרַתֵּהּ וּבְנוֹהִי הֲווֹ עִם גֵּיתוֹהִי בְּחַקְלָא וְשָׁתִיק יַעֲקֹב עַד מֵיתֵיהוֹן:
@56 וּנְפַק חֲמוֹר אֲבוּהִי דִּשְׁכֶם לְוַת יַעֲקֹב לְמַלָּלָא עִמֵּהּ:
@57 וּבְנֵי יַעֲקֹב עַלּוּ מִן חַקְלָא כַּד שְׁמָעוּ וְאִתְנְסִיסוּ גֻּבְרַיָּא וּתְקֵיף לְהוֹן לַחֲדָא אֲרֵי קְלָנָא עֲבַד בְּיִשְׂרָאֵל לְמִשְׁכַּב עִם בַּת יַעֲקֹב וְכֵן לָא כָשַׁר לְאִתְעֲבָדָא:
@58 וּמַלִּיל חֲמוֹר עִמְּהוֹן לְמֵימָר שְׁכֶם בְּרִי אִתְרְעִיאַת נַפְשֵׁהּ בִּבְרַתְּכוֹן הָבוּ כְעַן יָתַהּ לֵהּ לְאִנְתּוּ:
@59 וְתִתְחַתְּנוּן בָּנָא בְּנָתֵיכוֹן תִּתְּנוּן לָנָא וְיָת בְּנָתָנָא תִּסְבוּן לְכוֹן:
@60 וְעִמָּנָא תֵּתְבוּן וְאַרְעָא תְּהֵי קֳדָמֵיכוֹן תִּיבוּ וְעֲבִידוּ בַהּ סְחוֹרְתָּא וְאַחֲסִינוּ בַּהּ:
@61 וַאֲמַר שְׁכֶם לַאֲבוּהָא וּלְאַחָהָא אַשְׁכַּח רַחֲמִין בְּעֵינֵיכוֹן וְדִי תֵימְרוּן לִי אֶתֵּן:
@62 אַסְגוּ עָלַי לַחֲדָא מוֹהֲרִין וּמַתְּנָן וְאֶתֵּן כְּמָא דִּי תֵימְרוּן לִי וְהָבוּ לִי יָת עוּלֶמְתָּא:לאִנְתּוּ:
@63 וַאֲתִיבוּ בְנֵי יַעֲקֹב יָת שְׁכֶם וְיָת חֲמוֹר אֲבוּהִי בְּחָכְמְתָא וּמַלִּילוּ דִּי סָאֵב יָת דִּינָה אֲחָתְהוֹן:
@64 וַאֲמָרוּ לְהוֹן לָא נִכּוּל לְמֶעְבַּד פִּתְגָּמָא הָדֵין לְמִתַּן יָת אֲחָתָנָא לִגְבַר דִּי לֵיהּ עָרְלְתָא אֲרֵי חִסּוּדָא הִיא לָנָא:
@65 בְּרַם בְּדָא נִתְפֵּס לְכוֹן אִם תֶּהֱווֹן כְּוָתָנָא לְמִגְזַר לְכוֹן כָּל דְּכוּרָא:
@66 וְנִתַּן יָת בְּנָתָנָא לְכוֹן וְיָת בְּנָתֵיכוֹן נִסַּב לָנָא וְנִתּוּב עִמְּכוֹן וְנֵיהֵי לְעַמָּא חָד:
@67 וְאִם לָא תְקַבְּלוּן מִנָּנָא לְמִגְזָר וּנְדַבֵּר יָת בְּרַתָּנָא וְנֵזֵיל:
@68 וּשְׁפָרוּ פִּתְגָּמֵיהוֹן בְּעֵינֵי חֲמוֹר וּבְעֵינֵי שְׁכֶם בַּר חֲמוֹר:
@69 וְלָא אוֹחַר עוּלֵימָא לְמֶעְבַּד פִּתְגָּמָא אֲרֵי אִתְרְעִי בְּבַת יַעֲקֹב וְהוּא יַקִּיר מִכֹּל בֵּית אֲבוּהִי:
@70 וַאֲתָא חֲמוֹר וּשְׁכֶם בְּרֵהּ לִתְרַע קַרְתְּהוֹן וּמַלִּילוּ עִם אֲנָשֵׁי קַרְתְּהוֹן לְמֵימָר:
@71 גֻּבְרַיָּא הָאִלֵּין שָׁלְמִין אִנּוּן עִמָּנָא וִיתִיבוּן בְּאַרְעָא וְיַעְבְּדוּן בַּהּ סְחוֹרְתָא וְאַרְעָא הָא פְתָיוּת יְדִין קֳדָמֵיהוֹן יָת בְּנָתֵיהוֹן נִסַּב לָנָא לִנְשִׁין וְיָת בְּנָתָנָא נִתֵּן לְהוֹן:
@72 בְּרַם בְּדָא יִתָּפְסוּן לָנָא גּוּבְרַיָּא לְמִתַּב עִמָּנָא לְמֶהֱוֵי לְעַמָּא חָד בְּמִגְזַר לָנָא כָּל דְּכוּרָא כְּמָא דִּי אִנּוּן גְּזִירִין:
@73 גֵּיתֵיהוֹן וְקִנְיָנְהוֹן וְכָל בְּעִירְהוֹן הֲלָא דִּילָנָא אִנּוּן בְּרַם נִתְפֵּס לְהוֹן וִיתִיבוּן עִמָּנָא:
@74 וְקַבִּילוּ מִן חֲמוֹר וּמִן שְׁכֶם בְּרֵהּ כָּל נָפְקֵי תְּרַע קַרְתֵּהּ וּגְזָרוּ כָּל דְּכוּרָא כָּל נָפְקֵי תְּרַע קַרְתֵּהּ:
@75 וַהֲוָה בְיוֹמָא תְלִיתָאָה כַּד תְּקִיפוּ עֲלֵיהוֹן כֵּאבֵיהוֹן וּנְסִיבוּ תְרֵין בְּנֵי יַעֲקֹב שִׁמְעוֹן וְלֵוִי אֲחֵי דִּינָה גְּבַר חַרְבֵּהּ וְעַלּוּ עַל קַרְתָּא דְּיָתְבוּן לְרָחֲצָן וּקְטָלוּ כָּל דְּכוּרָא:
@76 וְיָת חֲמוֹר וְיָת שְׁכֶם בְּרֵהּ קְטָלוּ לְפִתְגַּם דְּחָרֶב וּדְבָרוּ יָת דִּינָה מִבֵּית שְׁכֶם וּנְפָקוּ:
@77 בְּנֵי יַעֲקֹב עַלּוּ לְחַלָּצָא קָטִילַיָּא וּבְזוֹ קַרְתָּא דִּי סָאִיבוּ אֲחָתְהוֹן:
@78 יָת עָנְהוֹן וְיָת תּוֹרְהוֹן וְיָת חֲמָרֵיהוֹן וְיָת דִּי בְקַרְתָּא וְיָת דִּי בְחַקְלָא בְּזוֹ:
@79 וְיָת כָּל נִכְסֵיהוֹן וְיָת כָּל טַפְלְהוֹן וְיָת נְשֵׁיהוֹן שְׁבוֹ וּבְזוֹ וְיָת כָּל דִּי בְבֵיתָא:
@80 וַאֲמַר יַעֲקֹב לְשִׁמְעוֹן וּלְלֵוִי עֲכַרְתּוּן יָתִי לְמִתַּן דְּבָבוּ בֵּינָנָא וּבֵין יָתְבֵי אַרְעָא בִּכְנַעֲנָאָה וּבַפְּרִזָּאָה וַאֲנָא עַם דְּמִנְיַן וְיִתְכַּנְשׁוּן עֲלַי וְיִמְחִנּוּנִי וְאֶשְׁתֵּצֵי אֲנָא וְאֱנַשׁ בֵּיתִי:
@81 וַאֲמָרוּ הַכְנָפְקַת בָּרָא יִתְעֲבֵד (נ''א יַעְבֵּד יָת אַחָתָנָא) לַאֲחָתָנָא:
@82 וַאֲמַר יְיָ לְיַעֲקֹב קוּם סַק לְבֵית אֵל וְתִיב תַּמָן וְעִבֵּד תַּמָן מַדְבְּחָא לֵאלָהָא דְאִתְגְלִי לָךְ בְּמֵעִרְקָךְ מִן קֳדָם עֵשָׂו אָחוּךְ:
@83 וַאֲמַר יַעֲקֹב לֶאֱנַשׁ בֵּיתֵהּ וּלְכֹל דִּי עִמֵּהּ אַעְדוּ יָת טַעֲוַת עַמְמַיָּא דִי בֵינֵיכוֹן וְאִדַכּוּ וְשַׁנּוּ כְּסוּתְכוֹן:
@84 וְנֵקוֹם וְנִסַּק לְבֵית אֵל וְאֶעְבֵּד תַּמָּן מַדְבְּחָא לֵאלָהָא דְקַבִּיל צְלוֹתִי בְּיוֹמָא דְעַקְתִי וַהֲוָה מֵימְרֵהּ בְּסַעְדִי בְּאָרְחָא דִי אֲזָלִית:
@85 וִיהָבוּ לְיַעֲקֹב יָת כָּל טַעֲוַת עַמְמַיָּא דִי בִידֵיהוֹן וְיָת קָדָשַׁיָּא דִי בְאֻדְנֵיהוֹן וְטַּמַּר יָתְהוֹן יַעֲקֹב תְּחוֹת בָּטְמָא דִי עִם שְׁכֶם:
@86 וּנְטָלוּ וַהֲוַת דַּחֲלָא דַיְיָ עַל עַמְמַיָא דִי בְּקִרְוֵי סַחֲרָנֵיהוֹן וְלָא רְדָפוּ בָּתַר בְּנֵי יַעֲקֹב:
@87 וַאֲתָא יַעֲקֹב לְלוּז דִּי בְאַרְעָא דִכְנַעַן הִיא בֵּית אֵל הוּא וְכָל עַמָּא דִי עִמֵּהּ:
@88 וּבְנָא תַמָּן מַדְבְּחָא וּקְרָא לְאַתְרָא אֵל בֵּית אֵל אֲרֵי תַמָּן אִתְגְלֵי לֵהּ יְיָ בְּמֵעִרְקֵהּ מִן קֳדָם אָחוּהִי:
@89 וּמִיתַת דְּבוֹרָה מֵנִקְתָּא דְרִבְקָה וְאִתְקְבָרַת מִלְרַע לְבֵית אֵל בְּשִׁפּוֹלֵי מֵישְׁרָא וּקְרָא שְׁמֵּהּ מֵישַׁר בָּכִיתָא:
@90 וְאִתְגְלִי יְיָ לְיַעֲקֹב עוֹד בְּמֵיתוֹהִי מִפַּדַן אֲרָם וּבָרִיךְ יָתֵהּ:
@91 וַאֲמַר לֵהּ יְיָ שְׁמָךְ יַעֲקֹב לָא יִתְקְרֵי שְׁמָךְ עוֹד יַעֲקֹב אֶלָהֵין יִשְׂרָאֵל יְהֵא שְׁמָךְ וּקְרָא יָת שְׁמֵהּ יִשְׂרָאֵל:
@92 וַאֲמַר לֵהּ יְיָ אֲנָא אֵל שַׁדַּי פּוּשׁ וּסְגֵי עַם וְכִנְשַׁת שִׁבְטִּין יְהֵא מִנָּךְ וּמַלְכִין דְשַׁלִּיטִין בְּעַמְמַיָּא מִנָּךְ יִפְקוּן:
@93 וְיָת אַרְעָא דִי יְהָבִית לְאַבְרָהָם וּלְיִצְחָק לָךְ אֶתְּנִנַּהּ וְלִבְנָיךְ בַּתְרָךְ אֶתֵּן יָת אַרְעָא:
@94 וְאִסְתַּלַּק מֵעִלָּוֹהִי יְקָרָא דַיְיָ בְּאַתְרָא דִי מַלֵּיל עִמֵּהּ:
@95 וַאֲקֵם יַעֲקֹב קַמְתָא בְּאַתְרָא דִי מַלִּיל עִמֵּהּ קָמַת אַבְנָא וְאַסִּיךְ עֲלַהּ נִסּוּכִין וַאֲרִיק עֲלַהּ מִשְׁחָא:
@96 וּקְרָא יַעֲקֹב יָת שְׁמָא דְאַתְרָא דִי מַלִּיל עִמֵּהּ תַּמָּן יְיָ בֵּית אֵל:
@97 וּנְטָלוּ מִבֵּית אֵל וַהֲוָה עוֹד כְּרוּבַת אַרְעָא לְמֵיעַל לְאֶפְרָת וִילִידַת רָחֵל וְקַשִׁיאַת בְּמֵילְדַהּ:
@98 וַהֲוָה בְקַשְׁיוּתַהּ בְּמֵילְדַהּ וַאֲמֶרֶת לַהּ חָיְתָא לָא תִדְחֲלִי אֲרֵי אַף דֵּין לִיךְ בָּר:
@99 וַהֲוָה בְּמִפַּק נַפְשַׁהּ אֲרֵי מִיתַת (נ''י מַיְתָא) וּקְרַת שְׁמֵהּ בַּר דְוָי וַאֲבוּהִי קְרָא לֵהּ בִּנְיָמִין:
@100 וּמִיתַת רָחֵל וְאִתְקְבָרַת בְּאֹרַח אֶפְרָת הִיא בֵּית לָחֶם:
@101 וַאֲקֵים יַעֲקֹב קַמְתָא עַל קְבֻרְתַּהּ הִיא קָמַת קְבֻרְתָּא דְרָחֵל עַד יוֹמָא דֵין:
@102 וּנְטַל יִשְׂרָאֵל וּפְרַס מַשְׁכְּנֵהּ מִלְהַלָא לְמִגְדְלָא דְעֵדֶר:
@103 וַהֲוָה כַּד שְׁרָא יִשְׂרָאֵל בְּאַרְעָא הַהִיא וַאֲזַל רְאוּבֵן וּשְׁכִיב עִם בִּלְהָה לְחֵינָתָא דַאֲבוּהִי וּשְׁמַע יִשְׂרָאֵל וַהֲווֹ בְנֵי יַעֲקֹב תְּרֵי עֲסַר:
@104 בְּנֵי לֵאָה בּוּכְרָא דְיַעֲקֹב רְאוּבֵן וְשִׁמְעוֹן וְלֵוִי וִיהוּדָה וְיִשָׂשׂכָר וּזְבֻלוּן:
@105 בְּנֵי רָחֵל יוֹסֵף וּבִנְיָמִן:
@106 וּבְנֵי בִלְהָה אַמְתָא דְרָחֵל דָּן וְנַפְתָּלִי:
@107 וּבְנֵי זִלְפָּה אַמְתָא דְלֵאָה גָּד וְאָשֵׁר אִלֵּין בְּנֵי יַעֲקֹב דִּי אִתְיְלִידוּ לֵהּ בְּפַדַן אֲרָם:
@108 וַאֲתָא יַעֲקֹב לְוַת יִצְחָק אֲבוּהִי מַמְרֵא קִרְיַת אַרְבַּע הִיא חֶבְרוֹן דִּי דָר תַּמָּן אַבְרָהָם וְיִצְחָק:
@109 וַהֲווֹ יוֹמֵי יִצְחָק מְאָה וּתְמָנָן שְׁנִין:
@110 וְאִתְנְגִיד יִצְחָק וּמִית וְאִתְכְּנִישׁ לְעַמֵהּ סִיב וּשְׂבַע יוֹמִין וּקְבָרוּ יָתֵהּ עֵשָׂו וְיַעֲקֹב בְּנוֹהִי:
@111 וְאִלֵּין תּוּלְדַת עֵשָׂו הוּא אֱדוֹם:
@112 עֵשָׂו נְסִיב יָת נְשׁוֹהִי מִבְּנַת כְּנָעַן יָת עָדָה בַּת אֵילוֹן חִתָּאָה וְיָת אָהֳלִיבָמָה בַּת עֲנָה בַּת צִבְעוֹן חִוָאָה:
@113 וְיָת בָּשְׂמַת בַּת יִשְׁמָעֵאל אֲחָתֵהּ דִנְבָיוֹת:
@114 וִילִידַת עָדָה לְעֵשָׂו יָת אֱלִיפָז וּבָשְׂמַת יְלִידַת יָת רְעוּאֵל:
@115 וְאָהֳלִיבָמָה יְלִידַת יָת יְעוּשׁ וְיָת יַעְלָם וְיָת קֹרַח אִלֵּין בְּנֵי עֵשָׂו דִי אִתְיְלִידוּ לֵהּ בְּאַרְעָא דִכְנָעַן:
@116 וּדְבַר עֵשָׂו יָת נְשׁוֹהִי וְיָת בְּנוֹהִי וְיָת בְּנָתֵהּ וְיָת כָּל נַפְשַׁת בֵּיתֵהּ וְיָת גֵּיתוֹהִי וְיָת כָּל בְּעִירֵהּ וְיָת כָּל קִנְיָנֵהּ דִי קְנָא בְּאַרְעָא דִכְנָעַן וַאֲזַל לְאַרְעָא אוֹחֲרִי מִן קֳדָם יַעֲקֹב אָחוּהִי:
@117 אֲרֵי הֲוָה קִנְיָנְהוֹן סַגִּי מִלְמִתַּב כַּחֲדָא וְלָא יְכִילַת אֲרַע תּוֹתָבוּתְהוֹן לְסוֹבָרָא יָתְהוֹן מִן קֳדָם גֵּיתֵיהוֹן:
@118 וִיתֵיב עֵשָׂו בְּטוּרָא דְשֵׂעִיר עֵשָׂו הוּא אֱדוֹם:
@119 וְאִלֵּין תּוּלְדַת עֵשָׂו אֲבוּהוֹן דֶאֱדוֹמָאֵי בְּטוּרָא דְשֵׂעִיר:
@120 אִלֵּין שְׁמָהַת בְּנֵי עֵשָׂו אֱלִיפַז בַּר עָדָה אִתַּת עֵשָׂו רְעוּאֵל בַּר בָּשְׂמַת אִתַּת עֵשָׂו:
@121 וַהֲווֹ בְּנֵי אֱלִיפָז תֵּימָן אוֹמָר צְפוֹ וְגַעְתָּם וּקְנַז:
@122 וְתִמְנַע הֲוַת לְחֵינָתָא לֶאֱלִיפַז בַּר עֵשָׂו וִילִידַת לֶאֱלִיפַז יָת עֲמָלֵק אִלֵּין בְּנֵי עָדָה אִתַּת עֵשָׂו:
@123 וְאִלֵּין בְּנֵי רְעוּאֵל נַחַת וָזֶרַח שַׁמָּה וּמִזָה אִלֵּין הֲווֹ בְּנֵי בָשְׂמַת אִתַּת עֵשָׂו:
@124 וְאִלֵּין הֲווֹ בְּנֵי אָהֳלִיבָמָה בַת עֲנָה בַּת צִבְעוֹן אִתַּת עֵשָׂו וִילִידַת לְעֵשָׂו יָת יְעוּשׁ וְיָת יַעְלָם וְיָת קֹרַח:
@125 אִלֵּין רַבְרְבֵי בְנֵי עֵשָׂו בְּנֵי אֱלִיפַז בּוּכְרָא דְעֵשָׂו רַבָּא תֵּימָן רַבָּא אוֹמָר רַבָּא צְפוֹ רַבָּא קְנַז:
@126 רַבָּא קֹרַח רַבָּא גַעְתָּם רַבָּא עֲמָלֵק אִלֵּין רַבְרְבֵי אֱלִיפַז בְּאַרְעָא דֶאֱדוֹם אִלֵּין בְּנֵי עָדָה:
@127 וְאִלֵּין בְּנֵי רְעוּאֵל בַּר עֵשָׂו רַבָּא נַחַת רַבָּא זֶרַח רַבָּא שַׁמָה רַבָּא מִזָּה אִלֵּין רַבְרְבֵי רְעוּאֵל בְּאַרְעָא דֶאֱדוֹם אִלֵין בְּנֵי בָשְׂמַת אִתַּת עֵשָׂו:
@128 וְאִלֵּין בְּנֵי אָהֳלִיבָמָה אִתַּת עֵשָׂו רַבָּא יְעוּשׁ רַבָּא יַעְלָם רַבָּא קֹרַח אִלֵּין רַבְרְבֵי אָהֳלִיבָמָה בַּת עֲנָה אִתַּת עֵשָׂו:
@129 אִלֵּין בְּנֵי עֵשָׂו וְאִלֵּין רַבְרְבָנֵיהוֹן הוּא אֱדוֹם:
@130 אִלֵּין בְּנֵי שֵׂעִיר חוֹרָאָה יָתְבֵי דְּאַרְעָא לוֹטָן וְשׁוֹבָל וְצִבְעוֹן וַעֲנָה:
@131 וְדִישׁוֹן וְאֵצֶר וְדִישָׁן אִלֵּין רַבְרְבֵי חוֹרָאֵי בְּנֵי שֵׂעִיר בְּאַרְעָא דֶאֱדוֹם:
@132 וַהֲווֹ בְנֵי לוֹטָן חוֹרִי וְהֵימָם וַאֲחָתֵהּ דְלוֹטָן תִּמְנָע:
@133 וְאִלֵּין בְּנֵי שׁוֹבָל עַלְוָן וּמָנַחַת וְעֵיבָל שְׁפוֹ וְאוֹנָם:
@134 וְאִלֵּין בְּנֵי צִבְעוֹן וְאַיָּה וַעֲנָה הוּא עֲנָה דִּי אַשְׁכַּח יָתּ גִּבָּרַיָּא בְּמַדְבְּרָא כַּד הֲוָה רָעֵי יָת חֲמָרַיָּא לְצִבְעוֹן אֲבוּהִי:
@135 וְאִלֵּין בְּנֵי עֲנָה דִּשֹׁן וְאָהֳלִיבָמָה בַּת עֲנָה:
@136 וְאִלֵּין בְּנֵי דִישָׁן חֶמְדָן וְאֶשְׁבָּן וְיִתְּרָן וּכְרָן:
@137 אִלֵּין בְּנֵי אֵצֶר בִּלְהָן וְזַעֲוָן וַעֲקָן:
@138 אִלֵּין בְּנֵי דִישָׁן עוּץ וַאֲרָן:
@139 אִלֵּין רַבְרְבֵי חוֹרָאָה רַבָּא לוֹטָן רַבָּא שׁוֹבָל רַבָּא צִבְעוֹן רַבָּא עֲנָה:
@140 רַבָּא דִּשֹׁן רַבָּא אֵצֶר רַבָּא דִישָׁן אִלֵּין רַבְרְבֵי חוֹרָאָה לְרַבְרְבָנֵיהוֹן בְּאַרְעָא דְשֵׂעִיר:
@141 וְאִלֵּין מַלְכַיָּא דִי מְלִיכוּ בְּאַרְעָא דֶאֱדוֹם קֳדָם דִּי מְלַךְ מַלְכָּא לִבְנֵי יִשְׂרָאֵל:
@142 וּמְלַךְ בֶּאֱדוֹם בֶּלַע בַּר בְּעוֹר וְשׁוּם קַרְתֵּהּ דִּנְהָבָה:
@143 וּמִית בָּלַע וּמְלַךְ תְּחוֹתוֹהִי יוֹבָב בַּר זֶרַח מִבָּצְרָה:
@144 וּמִית יוֹבָב וּמְלַךְ תְּחוֹתוֹהִי חֻשָׁם מֵאַרְעָא דָרוֹמָא:
@145 וּמִית חֻשָׁם וּמְלַךְ תְּחוֹתוֹהִי הֲדַד בַּר בְּדַד דִקְטִיל יָת מִדְיָנָאֵי בְּחַקְלָא דְמוֹאָב וְשׁוּם קַרְתֵּהּ עֲוִית:
@146 וּמִית הֲדָד וּמְלַךְ תְּחוֹתוֹהִי שַׂמְלָה מִמַשְׂרֵקָה:
@147 וּמִית שַׂמְלָה וּמְלַךְ תְּחוֹתוֹהִי שָׁאוּל מֵרְחוֹבוֹת דְעַל פְּרָת:
@148 וּמִית שָׁאוּל וּמְלַךְ תְּחוֹתוֹהִי בַּעַל חָנָן בַּר עַכְבּוֹר:
@149 וּמִית בַּעַל חָנָן בַּר עַכְבּוֹר וּמְלַךְ תְּחוֹתוֹהִי הֲדַר וְשׁוּם קַרְתֵּהּ פָּעוּ וְשׁוּם אִתְּתֵהּ מְהֵיטַבְאֵל בַּת מַטְּרֵד בַת מְצָרֵף דַּהֲבָא:
@150 וְאִלֵּין שְׁמָהַת רַבְרְבֵי עֵשָׂו לְזַרְעֲיָתְהוֹן לְאַתְרֵיהוֹן בִּשְׁמָהַתְהוֹן רַבָּא תִמְנָע רַבָּא עַלְוָה רַבָּא יְתֵת:
@151 רַבָּא אָהֳלִיבָמָה רַבָּא אֵלָה רַבָּא פִּינֹן:
@152 רַבָּא קְנַז רַבָּא תֵימָן רַבָּא מִבְצָר:
@153 רַבָּא מַגְדִיאֵל רַבָּא עִירָם אִלֵּין רַבְרְבֵי אֱדוֹם לְמוֹתְבָנְהוֹן בְּאַרְעָא אַחֲסַנְתְּהוֹן הוּא עֵשָׂו אֲבוּהוֹן דֶאֱדוֹמָאֵי: פפפ:

@1 **וישלח יעקב מלאכים.** מלאכים ממש: **ארצה שעיר.** לארץ שעיר, כל תיבה שצריכה למ''ד בתחלתה הטיל לה הכתוב ה''א בסופה:
@2 **גרתי.** לא נעשיתי שר וחשוב אלא גר, אינך כדאי לשנוא אותי על ברכות אביך שברכני (לעיל כז כט) הוה גביר לאחיך, שהרי לא נתקימה בי. דבר אחר גרתי בגימטריא תרי''ג, כלומר עם לבן הרשע גרתי ותרי''ג מצות שמרתי ולא למדתי ממעשיו הרעים:
@3 **ויהי לי שור וחמור.** אבא אמר לי (כז כח) מטל השמים ומשמני הארץ, זו אינה לא מן השמים ולא מן הארץ: **שור וחמור.** דרך ארץ לומר על שורים הרבה שור. אדם אומר לחברו בלילה קרא התרנגול, ואינו אומר קראו התרנגולים: **ואשלחה להגיד לאדוני.** להודיע שאני בא אליך: **למצא חן בעיניך.** שאני שלם עמך ומבקש אהבתך:
@4 **באנו אל אחיך אל עשו.** שהיית אומר אחי הוא, אבל הוא נוהג עמך כעשו הרשע, עודנו בשנאתו:
@5 **ויירא ויצר.** ויירא שמא יהרג, ויצר לו אם יהרוג הוא את אחרים:
@6 **המחנה האחת והכהו.** מחנה משמש לשון זכר ולשון נקבה. (תהלים כז ג) אם תחנה עלי מחנה, הרי לשון נקבה, (לג ח) המחנה הזה, לשון זכר. וכן יש שאר דברים משמשים לשון זכר ולשון נקבה, (לעיל יט כג) השמש יצא על הארץ, (תהלים יט ז) מקצה השמים מוצאו, הרי לשון זכר. (מ''ב ג כב) והשמש זרחה על המים, הרי לשון נקבה. וכן רוח (איוב א יט) והנה רוח גדולה באה, הרי לשון נקבה, (שם) ויגע בארבע פנות הבית, הרי לשון זכר, (מ''א יט יא) ורוח גדולה וחזק מפרק הרים, הרי לשון זכר ולשון נקבה. וכן אש (במדבר טז לה) ואש יצאה מאת ה', לשון נקבה. (תהלים קד ד) אש לוהט, לשון זכר: **והיה המחנה הנשאר לפלטה.** על כרחו כי אלחם עמו. התקין עצמו לשלשה דברים לדורון, לתפלה ולמלחמה. לדורון להלן (פסוק כא) ותעבור המנחה על פניו. לתפלה (פסוק ט) אלהי אבי אברהם. למלחמה והיה המחנה הנשאר לפלטה:
@7 **ואלהי אבי יצחק.** ולהלן הוא אומר (לא מב) ופחד יצחק, ועוד מהו שחזר והזכיר שם המיחד, היה לו לכתוב האומר אלי שוב לארצך וגו' . אלא כך אמר יעקב לפני הקדוש ברוך הוא שתי הבטחות הבטחתני אחת בצאתי מבית אבי מבאר שבע, שאמרת לי (כח יג) אני ה' אלהי אברהם אביך ואלהי יצחק, ושם אמרת לי (שם טו) ושמרתיך בכל אשר תלך. ובבית לבן אמרת לי (לא ג) שוב אל ארץ אבותיך ולמולדתך ואהיה עמך, ושם נגלית אלי בשם המיחד לבדו, שנאמר (לא ג) ויאמר ה' אל יעקב שוב אל ארץ אבותיך וגו' , בשתי הבטחות האלו אני בא לפניך:
@8 **קטנתי מכל החסדים.** נתמעטו זכיותי על ידי החסדים והאמת שעשית עמי, לכך אני ירא, שמא משהבטחתני נתלכלכתי בחטא ויגרום לי להמסר ביד עשו: **ומכל האמת.** אמתת דבריך, ששמרת לי כל ההבטחות שהבטחתני: **כי במקלי.** לא היה עמי לא כסף ולא זהב ולא מקנה אלא מקלי לבדו. ומדרש אגדה נתן מקלו בירדן ונבקע הירדן:
@9 **מיד אחי מיד עשו.** מיד אחי שאין נוהג עמי כאח אלא כעשו הרשע:
@10 **היטב איטיב.** היטב בזכותך, איטיב בזכות אבותיך: **ושמתי את זרעך כחול הים.** והיכן אמר לו כן, והלא לא אמר לו אלא (שם כח יד) והיה זרעך כעפר הארץ. אלא שאמר לו (כח טו) כי לא אעזבך עד אשר אם עשיתי את אשר דברתי לך, ולאברהם אמר (כב יז) הרבה ארבה את זרעך ככוכבי השמים וכחול אשר על שפת הים:
@11 **הבא בידו.** ברשותו, וכן (במדבר כא כו) ויקח את כל ארצו מידו. ומדרש אגדה מן הבא בידו אבנים טובות ומרגליות, שאדם צר בצרור ונושאם בידו. דבר אחר מן הבא בידו מן החלין, שנטל מעשר, כמה דאת אמר (כח כב) עשר אעשרנו לך, והדר לקח מנחה:
@12 **עזים מאתים ותישים עשרים.** מאתים עזים צריכות עשרים תישים, וכן כלם, הזכרים כדי צורך הנקבות. ובבראשית רבה (עו ז) דורש מכאן לעונה האמורה בתורה, הטילים בכל יום, הפועלים שתים בשבת, החמרים אחת בשבת, הגמלים אחת לשלשים יום, הספנים אחת לששה חדשים. ואיני יודע לכון המדרש הזה בכוון. אך נראה בעיני שלמדנו מכאן שאין העונה שוה בכל אדם אלא לפי טורח המטל עליו, שמצינו כאן שמסר לכל תיש עשרה עזים, וכן לכל איל, לפי שהם פנוים ממלאכה, דרכן להרבות בתשמיש לעבר עשר נקבות, ובהמה משנתעברה אינה מקבלת זכר, ופרים שעוסקין במלאכה לא מסר לזכר אלא ארבע נקבות, ולחמור שהולך בדרך רחוקה שתי נקבות לזכר, ולגמלים שהולכים דרך יותר רחוקה נקבה אחת לזכר:
@13 **גמלים מיניקות** וט' **שלשים.** ובניהם עמהם. ומדרש אגדה ובניהם בנאיהם, זכר כנגד נקבה, ולפי שצנוע בתשמיש לא פרסמו הכתוב: **ועירים.** חמורים זכרים:
@14 **עדר עדר לבדו.** כל מין ומין לעצמו: **עברו לפני.** דרך יום או פחות, ואני אבא אחריכם: **ורוח תשימו.** עדר לפני חברו מלא עין, כדי להשביע עינו של רשע ולתוהו על רבוי הדורון:
@15 **למי אתה.** שלמי אתה, מי שולחך, ותרגומו דמן את: **ולמי אלה לפניך.** ואלה שלפניך שלמי הם, למי המנחה הזאת שלוחה. למ''ד משמשת בראש התבה במקום של, כמו (לעיל לא מג) וכל אשר אתה רואה לי הוא, שלי הוא, (תהלים כד א) לה' הארץ ומלואה, של ה':
@16 **ואמרת לעבדך ליעקב.** על ראשון ראשון ועל אחרון אחרון, ששאלת (פסוק יז. יח) למי אתה, לעבדך ליעקב אני, ותרגומו דעבדך דיעקב, וששאלת (פסוק יז. יח) ולמי אלה לפניך, מנחה היא שלוחה וגו' : **והנה גם הוא.** יעקב:
@18 **אכפרה פניו.** אבטל רגזו וכן (ישעיה כח יח) וכפר בריתכם את מות, (שם מז יא) לא תוכלי כפרה. ונראה בעיני שכל כפרה שאצל עוון וחטא ואצל פנים כלן לשון קנוח והעברה הן, ולשון ארמי הוא הרבה בתלמוד (ב''מ כד א) וכפר ידה, (גיטין נו א) בעי לכפורי ידה בההוא גברא, וגם בלשון המקראנקראים המזרקים של קדש (עזרא א י) כפורי זהב, על שם שהכהן מקנח ידיו בהן בשפת המזרק:
@19 **על פניו.** כמו לפניו, וכן (ירמיה ו ז) חמס ושד ישמע בה על פני תמיד, וכן (ישעיה סה ג) המכעסים אתי על פני. ומדרש אגדה על פניו אף הוא שרוי בכעס, שהיה צריך לכל זה:
@20 **ואת אחד עשר ילדיו.** ודינה היכן היתה, נתנה בתבה ונעל בפניה שלא יתן בה עשו עיניו, ולכך נענש יעקב שמנעה מאחיו שמא תחזירנו למוטב, ונפלה ביד שכם: **יבק.** שם הנהר:
@21 **את אשר לו.** הבהמות והמטלטלין, עשה עצמו כגשר, נוטל מכאן מניח כאן:
@22 **ויותר יעקב.** שכח פכים קטנים וחזר עליהם: **ויאבק איש.** מנחם פרש ויתעפר איש, לשון אבק, שהיו מעלים עפר ברגליהם על ידי נענועם. ולי נראה שהוא לשון ויתקשר, ולשון ארמי הוא, בתר דאביקו בה, ואבק לה מיבק, לשון עניבה, שכן דרך שנים שמתעצמים להפיל איש את רעהו שחובקו ואובקו בזרועותיו. ופירשו רבותינו זכרונם לברכה שהוא שרו של עשו:
@23 **ויגע בכף ירכו.** קלית הירך התקוע בקלבוסית קרוי כף, על שם שהבשר שעליה כמין כף של קדרה: **ותקע.** נתקעקעה ממקום מחברתה, ודומה לו (ירמיה ו ח) פן תקע נפשי ממך, לשון הסרה. ובמשנה לקעקע ביצתן, לשרש שרשיהן:
@24 **כי עלה השחר.** וצריך אני לומר שירה ביום: **ברכתני.** הודה לי על הברכות שברכני אבי, שעשו מערער עליהן:
@26 **לא יעקב.** לא יאמר עוד שהברכות באו לך בעקבה וברמיה כי אם בשררה ובגלוי פנים, וסופך שהקדוש ברוך הוא נגלה עליך בבית אל ומחליף את שמך, ושם הוא מברכך, ואני שם אהיה ואודה לך עליהן, וזהו שכתוב (הושע יב ה) וישר אל מלאך ויכל בכה ויתחנן לו, בכה המלאך ויתחנן לו, ומה נתחנן לו (שם) בית אל ימצאנו ושם ידבר עמנו, המתן לי עד שידבר עמנו שם, ולא רצה יעקב, ועל כרחו הודה לו עליהן, וזהו (פסוק ל) ויברך אותו שם, שהיה מתחנן להמתין לו ולא רצה: **ועם אנשים.** עשו ולבן: **ותוכל.** להם:
@27 **למה זה תשאל.** אין לנו שם קבוע, משתנין שמותינו, הכל לפי מצות עבודת השליחות שאנו משתלחים:
@29 **ויזרח לו השמש.** לשון בני אדם הוא, כשהגענו למקום פלוני האיר לנו השחר, זהו פשוטו. ומדרש אגדה ויזרח לו לצרכו, לרפאות את צלעתו, כמה דתימא (מלאכי ג כ) שמש צדקה ומרפא בכנפיה, ואותן שעות שמיהרה לשקוע בשבילו כשיצא מבאר שבע, מהרה לזרוח בשבילו: **והוא צלע.** והוא היה צולע כשזרחה השמש:
@30 **גיד הנשה.** ולמה נקרא שמו גיד הנשה, לפי שנשה ממקומו ועלה, והוא לשון קפיצה, וכן (ירמיה נא ל) נשתה גבורתם, וכן (לקמן מא נא) כי נשני אלהים את כל עמלי:
@32 **ואת לאה וילדיה אחרנים.** אחרון אחרון חביב:
@33 **עבר לפניהם.** אמר אם יבא אותו רשע להלחם, ילחם בי תחלה:
@34 **ויחבקהו.** נתגלגלו רחמיו כשראהו משתחוה כל השתחואות הללו: **וישקהו.** נקוד עליו, ויש חולקין בדבר הזה בברייתא דספרי (בהעלותך סט) , יש שדרשו נקדה זו לומר שלא נשקו בכל לבו. אמר ר' שמעון בן יוחאי הלכה היא בידוע שעשו שונא ליעקב, אלא שנכמרו רחמיו באותה שעה ונשקו בכל לבו:
@35 **מי אלה לך.** מי אלה להיות שלך:
@37 **נגש יוסף ורחל.** בכלן האמהות נגשות לפני הבנים, אבל ברחל יוסף נגש לפניה, אמר אמי יפת תאר, שמא יתלה בה עיניו אותו רשע, אעמד כנגדה ואעכבנו מלהסתכל בה, מכאן זכה יוסף לברכת (מט כב) עלי עין:
@38 **מי לך כל המחנה.** מי כל המחנה אשר פגשתי שהוא שלך, כלומר למה הוא לך. ופשוטו של מקרא [נאמר] על מוליכי המנחה. ומדרשו כתות של מלאכים פגע, שהיו דוחפין אותו ואת אנשיו, ואומרים להם של מי אתם, והם אומרים להם של עשו, והן אומרים הכו הכו, ואלו אומרים הניחו בנו של יצחק הוא, ולא היו משגיחים עליו, בן בנו של אברהם הוא, ולא היו משגיחים, אחיו של יעקב הוא, אומרים להם אם כן משלנו אתם:
@39 **יהי לך אשר לך.** כאן הודה לו על הברכות:
@40 **אל נא.** אל נא תאמר לי כן: **אם נא מצאתי חן בעיניך ולקחת מנחתי מידי כי על כן ראיתי פניך** וגו' **.** כי כדאי והגון לך שתקבל מנחתי על אשר ראיתי פניך, והן חשובין לי כראית פני המלאך שראיתי שר שלך, ועוד על שנתרצית למחול סרחני. ולמה הזכיר לו ראית המלאך, כדי שיתירא המנו ויאמר ראה מלאכים ונצול, איני יכול לו מעתה: **ותרצני.** נתפיסת לי, וכן כל רצון שבמקרא לשון פיוס, אפיימינ''ט בלע''ז (ויקרא כב כ) כי לא לרצון יהיה לכם, הקרבנות באות לפיס ולרצון, וכן (משלי י לב) שפתי צדיק ידעון רצון, יודעים לפיס ולרצות:
@41 **ברכתי.** מנחתי, מנחה זו הבאה על ראית פנים ולפרקים אינה באה אלא לשאילת שלום, וכל ברכה שהיא לראית פנים, כגון להלן (מז י) ויברך יעקב את פרעה, (מ''ב יח לא) עשו אתי ברכה, דסנחריב. וכן (ש''ב ח י) לשאל לו לשלום ולברכו, דתועי מלך חמת, כלם לשון ברכת שלום הן שקורין בלע''ז שלוצי''ר [לשאול בשלום], אף זו ברכתי מו''ן שלו''ד : **אשר הבאת לך.** לא טרחת בה, ואני יגעתי להגיעה עד שבאה לידך: **חנני.** נו''ן ראשונה מדגשת לפי שהיא משמשת במקום שתי נוני''ן, שהיה לו לומר חננני, שאין חנן בלא שתי נונין, והשלישית לשמוש כמו עשני, זבדני: **יש לי כל.** כל ספוקי, ועשו דבר בלשון גאוה (פסוק ט) יש לי רב, יותר ויותר מכדי צרכי:
@42 **נסעה.** כמו (תהלים קל ב) שמעה, שהוא כמו שמע, אף כאן נסעה כמו נסע, והנו''ן יסוד בתבה. ותרגומו טול ונהך, עשו אמר ליעקב נסע מכאן ונלך: **ואלכה לנגדך.** בשוה לך, טובה זו אעשה לך שאאריך ימי מהלכתי ללכת לאט כאשר אתה צריך, וזהו לנגדך, בשוה לך:
@43 **עלות עלי.** הצאן והבקר שהן עלות מטלות עלי לנהלן לאט: **עלות.** מגדלות עולליהן, לשון (איכה ב יא) עולל ויונק, (ישעיה סה כ) עול ימים, (שמואל א' ו י) ושתי פרות עלות, ובלע''ז אינפנטיי''ש **ודפקום יום אחד.** ליגעם בדרך במרוצה, ומתו כל הצאן: **ודפקום.** כמו (שה''ש ה ב) קול דודי דופק, נוקש בדלת:
@44 **יעבר נא אדני.** אל תאריך ימי הליכתך, עבור כפי דרכך ואף אם תתרחק: **אתנהלה.** אתנהל, ה''א יתרה כמו (לעיל יח כא) ארדה, (במדבר ט ח) אשמעה: **לאטי.** לאט שלי, לשון נחת (ישעיה ח ו) ההולכים לאט, (ש''ב יח ה) לאט לי לנער. לאטי הלמ''ד מן היסוד ואינה משמשת, אתנהל נחת שלי: **לרגל המלאכה.** לפי צורך הליכת רגלי המלאכה המטלת עלי להוליך: **ולרגל הילדים.** לפי רגליהם שהם יכולים לילך: **עד אשר אבא אל אדני שעירה.** הרחיב לו הדרך, שלא היה דעתו ללכת אלא עד סכות. אמר אם דעתו לעשות לי רעה ימתין עד בואי אצלו, והוא לא הלך. ואימתי ילך, בימי המשיח, שנאמר (עובדיה א כא) ועלו מושעים בהר ציון לשפט את הר עשו. ומדרשי אגדה יש לפרשה זו רבים:
@45 **ויאמר למה זה.** תעשה לי טובה זו שאיני צריך לה: **אמצא חן בעיני אדני.** ולא תשלם לי עתה שום גמול:
@46 **וישב ביום ההוא עשו לדרכו.** עשו לבדו וארבע מאות איש שהלכו עמו נשמטו מאצלו אחד אחד. והיכן פרע להם הקדוש ברוך הוא, בימי דוד, שנאמר (ש''א ל יז) כי אם ארבע מאות איש נער אשר רכבו על הגמלים:
@47 **ויבן לו בית.** שהה שם שמונה עשר חדש, קיץ וחרף וקיץ. סכות קיץ, בית חורף, סכות קיץ:
@48 **שלם.** שלם בגופו, שנתרפא מצליעתו. שלם בממונו, שלא חסר כלום מכל אותו דורון. שלם בתורתו, שלא שכח תלמודו בבית לבן: **עיר שכם.** כמו לעיר, וכמוהו (רות א יט) עד בואנה בית לחם: **בבאו מפדן ארם.** כאדם האומר לחברו יצא פלוני מבין שני אריות ובא שלם, אף כאן ויבא שלם מפדן ארם, מלבן ומעשו שנזדוגו לו בדרך:
@49 **קשיטה.** מעה. אמר רבי עקיבא כשהלכתי לכרכי הים היו קורין למעה קשיטה (ותרגומו חרפן, טובים, חריפים בכל מקום, כגון עובר לסוחר) :
@50 **ויקרא לו אל אלהי ישראל.** לא שהמזבח קרוי אלהי ישראל, אלא על שם שהיה הקדוש ברוך הוא עמו והצילו קרא שם המזבח על שם הנס, להיות שבחו של מקום נזכר בקריאת השם, כלומר מי שהוא אל הוא הקדוש ברוך הוא הוא לאלהים לי ששמי ישראל, וכן מצינו במשה (שמות יז טו) ויקרא שמו ה' נסי, לא שהמזבח קרוי ה', אלא על שם הנס קרא שם המזבח, להזכיר שבחו של הקדוש ברוך הוא, ה' הוא נסי. ורבותינו דרשוהו שהקדוש ברוך הוא קראו ליעקב אל. ודברי תורה (ירמיה כג כט) כפטיש יפצץ סלע, מתחלקים לכמה טעמים, ואני לישב פשוטו ושמועו של מקרא באתי:
@51 **בת לאה.** ולא בת יעקב, אלא על שם יציאתה נקראת בת לאה, שאף היא יצאנית היתה, שנאמר (ל טז) ותצא לאה לקראתו (ועליה משלו המשל (יחזקאל טז מד) כאמה בתה) :
@52 **וישכב אתה.** כדרכה: **ויענה.** שלא כדרכה:
@53 **על לב הנערה.** דברים המתישבין על הלב, ראי אביך בחלקת שדה קטנה כמה ממון בזבז, אני אשאך ותקני העיר וכל שדותיה:
@57 **וכן לא יעשה.** לענות את הבתולות, שהאמות גדרו עצמן מן העריות על ידי המבול:
@58 **חשקה.** חפצה:
@62 **מהר.** כתבה:
@63 **במרמה.** בחכמה: **אשר טמא.** הכתוב אומר שלא היתה רמיה, שהרי טמא את דינה אחותם:
@64 **חרפה הוא.** שמץ פסול הוא אצלנו, הבא לחרף חברו הוא אומר לו ערל אתה, או בן ערל. חרפה בכל מקום גדוף:
@65 **נאות לכם.** נתרצה לכם, לשון (מ''ב יב ט) ויאותו: **להמל.** להיות נמול, אינו לשון לפעול אלא לשון להפעל:
@66 **ונתנו.** נו''ן שניה מדגשת, לפי שהיא משמשת במקום שתי נוני''ן ונתננו: **ואת בנתיכם נקח לנו.** אתה מוצא בתנאי שאמר חמור ליעקב ובתשובת בני יעקב לחמור שתלו החשיבות בבני יעקב, לקח בנות שכם את שיבחרו להם ובנותיהם יתנו להם לפי דעתם, דכתיב ונתנו את בנותינו, לפי דעתנו, ואת בנותיכם נקח לנו, ככל אשר נחפוץ. וכשדברו חמור ושכם בנו אל יושבי עירם הפכו הדברים (פסוק כא) את בנתם נקח לנו לנשים ואת בנתינו נתן להם, כדי לרצותם שיאותו להמול:
@71 **שלמים.** בשלום ובלב שלם: **והארץ הנה רחבת ידים.** כאדם שידו רחבה וותרנית, כלומר לא תפסידו כלום, פרקמטיא הרבה באה לכאן ואין לה קונים:
@72 **בהמול.** בהיות נמול:
@73 **אך נאותה להם.** לדבר זה, ועל ידי כן ישבו אתנו:
@75 **שני בני יעקב.** בניו היו, ואף על פי כן נהגו עצמן שמעון ולוי, כשאר אנשים שאינם בניו, שלא נטלו עצה המנו: **אחי דינה.** לפי שמסרו עצמן עליה נקראו אחיה: **בטח.** שהיו כואבים. ומדרש אגדה בטוחים היו על כחו של זקן:
@77 **על החללים.** לפשט את החללים:
@79 **חילם.** ממונם וכן (דברים ח יז) עשה לי את החיל הזה, (במדבר כד יח) וישראל עשה חיל, (תהלים מט יא) ועזבו לאחרים חילם: **שבו.** לשון שביה לפיכך טעמו מלרע:
@80 **עכרתם.** לשון מים עכורים, אין דעתי צלולה עכשיו. ואגדה, צלולה היתה החבית ועכרתם אותה, מסורת היתה ביד כנענים שיפלו ביד בני יעקב, אלא שהיו אומרים (שמות כג ל) עד אשר תפרה ונחלת את הארץ, לפיכך היו שותקין: **מתי מספר.** אנשים מועטים:
@81 **הכזונה.** הפקר: **את אחותנו.** ית אחתנא:
@82 **קום עלה.** לפי שאחרת בדרך נענשת ובא לך זאת מבתך:
@83 **הנכר.** שיש בידכם משלל שלשכם: **והטהרו.** מעבודה זרה: **והחליפו שמלתיכם.** שמא יש בידכם כסות של עבודה זרה:
@85 **האלה.** מין אילן סרק: **עם שכם.** אצל שכם:
@86 **חתת.** פחד:
@88 **אל בית אל.** הקדוש ברוך הוא בבית אל גלוי שכינתו בבית אל. יש תבה חסרה בי''ת המשמשת בראשה, כמו (ש''ב ט ד) הנה הוא בית מכיר בן עמיאל, כמו בבית מכיר, (להלן לח יא) בית אביך כמו בבית אביך: **נגלו אליו האלהים.** במקומות הרבה יש שם אלהות ואדנות בלשון רבים, כמו (להלן לט כ) אדני יוסף, (שמות כב יד) אם בעליו עמו, ולא נאמר בעלו, וכן אלהות שהוא לשון שופט ומרות נזכר בלשון רבים, אבל אחד מכל שאר השמות לא תמצא בלשון רבים:
@89 **ותמת דברה.** מה ענין דבורה בבית יעקב, אלא לפי שאמרה רבקה ליעקב (כז מה) ושלחתי ולקחתיך משם, שלחה דבורה אצלו לפדן ארם לצאת משם, ומתה בדרך. מדברי רבי משה הדרשן למדתיה: **מתחת לבית אל.** העיר יושבת בהר ונקברה ברגלי ההר: **תחת האלון.** בשפולי מישרא, שהיה מישור מלמעלה בשפוע ההר והקבורה מלמטה, ומישור של בית אל היו קורין לו אלון. ואגדה נתבשר שם באבל שני, שהגד לו על אמו שמתה. ואלון בלשון יוני אחר. ולפי שהעלימו את יום מותה, שלא יקללו הבריות הכרס שיצא ממנו עשו, אף הכתוב לא פרסמו:
@90 **עוד.** פעם שני במקום הזה, אחד בלכתו ואחד בשובו: **ויברך אתו.** ברכת אבלים:
@91 **לא יקרא שמך עוד יעקב.** לשון אדם הבא במארב ועקבה אלא לשון שר ונגיד:
@92 **אני אל שדי.** שאני כדאי לברך, שהברכות שלי: **פרה ורבה.** על שם שעדין לא נלד בנימין ואף על פי שכבר נתעברה ממנו: **גוי.** בנימין: **גוים.** מנשה ואפרים שעתידים לצאת מיוסף, והם במנין השבטים: **ומלכים.** שאול ואיש בשת שהיו משבט בנימין, שעדין לא נלד. (ופסוק זה דרשו אבנר כשהמליך איש בשת, ואף השבטים דרשוהו וקרבו בנימין, דכתיב (שופטים כא א) איש ממנו לא יתן את בתו לבנימן לאשה, וחזרו ואמרו אלמלא היה עולה מן השבטים לא היה הקדוש ברוך הוא אומר ליעקב ומלכים מחלציך יצאו) : **גוי וקהל גוים.** שגוים עתידים בניו להעשות כמנין הגוים שהם שבעים אמות, וכן כל הסנהדרין שבעים. דבר אחר שעתידים בניו להקריב אסור במות כגוים בימי אליהו:
@95 **במקום אשר דבר אתו.** איני יודע מה מלמדנו:
@97 **כברת הארץ.** מנחם פרש לשון כביר, רבוי, מהלך רב. ואגדה בזמן שהארץ חלולה ומנקבת ככברה שהניר מצוי, הסתו עבר, והשרב עדין לא בא. ואין זה פשוטו של מקרא, שהרי בנעמן מצינו (מ''ב ה יט) וילך מאתו כברת ארץ. ואומר אני שהוא שם מדת קרקע כמו מהלך פרסה או יותר, כמו שאתה אומר (ישעיה ה י) צמדי כרם, (לעיל לג יט) חלקת השדה, כך במהלך אדם נותן שם מדה כברת ארץ:
@98 **כי גם זה.** נוסף לך על יוסף. ורבותינו דרשו עם כל שבט נלדה תאומה, ועם בנימין נלדה תאומה יתרה:
@99 **בן אוני.** בן צערי: **בנימין.** נראה בעיני לפי שהוא לבדו נלד בארץ כנען, שהיא בנגב כשאדם בא מארם נהרים, כמו שנאמר (במדבר לג מ) בנגב בארץ כנען, (לעיל יב ט) הלוך ונסוע הנגבה: **בנימין.** בן ימין, לשון (תהלים פט יג) צפון וימין אתה בראתם, לפיכך הוא מלא:
@103 **בשכן ישראל בארץ ההוא.** עד שלא בא לחברון אצל יצחק ארעוהו כל אלה: **וישכב.** מתוך שבלבל משכבו מעלה עליו הכתוב כאלו שכבה. ולמה בלבל וחלל יצועו, שכשמתה רחל נטל יעקב מטתו שהיתה נתונה תדיר באהל רחל ולא בשאר אהלים ונתנה באהל בלהה, בא ראובן ותבע עלבון אמו, אמר אם אחות אמי היתה צרה לאמי, שפחת אחות אמי תהא צרה לאמי, לכן בלבל: **ויהיו בני יעקב שנים עשר.** מתחיל לענין ראשון משנלד בנימין נשלמה המטה, ומעתה ראוים להמנות, ומנאן. ורבותינו דרשו ללמדנו בא שכלן שוין, וכלן צדיקים, שלא חטא ראובן:
@104 **בכור יעקב.** אפלו בשעת הקלקלה קראו בכור: **בכור יעקב.** בכור לנחלה, בכור לעבודה, בכור למנין, ולא נתנה בכורה ליוסף אלא לענין השבטים שנעשה לשני שבטים:
@108 **ממרא.** שם המישור: **קרית הארבע.** שם העיר ממרא קרית הארבע אל מישור של קרית ארבע. ואם תאמר היה לו לכתוב ממרא הקרית ארבע, כן דרך המקרא בכל דבר ששמו כפול, כגון זה, וכגון בית לחם, אבי עזר, בית אל, אם הוצרך להטיל בו ה''א נותנה בראש התבה השניה (ש''א טז א) בית הלחמי, (שופטים ו כד) בעפרת אבי העזרי, (מ''א טז לד) בנה חיאל בית האלי:
@110 **ויגוע יצחק.** אין מקדם ומאחר בתורה, מכירתו של יוסף קדמה למיתתו של יצחק שתים עשרה שנה, שהרי כשנלד יעקב היה יצחק בן ששים שנה, שנאמר (לעיל כה כו) ויצחק בן ששים שנה וגו' , ויצחק מת בשנת מאה ועשרים ליעקב, אם תוציא ששים ממאה ושמונים שנה, נשארו מאה ועשרים, ויוסף נמכר בן שבע עשרה שנה, ואותה שנה שנת מאה ושמונה ליעקב. כיצד, בן ששים ושלש נתברך, וארבע עשרה שנה נטמן בבית עבר, הרי שבעים ושבע, וארבע עשרה עבד באשה, ובסוף ארבע עשרה נלד יוסף, שנאמר (לעיל ל כה) ויהי כאשר ילדה רחל את יוסף וגו' , הרי תשעים ואחת, ושבע עשרה עד שלא נמכר יוסף הרי מאה ושמנה. (עוד מפורש מן המקרא משנמכר יוסף עד שבא יעקב מצרימה עשרים ושתים שנה, שנאמר (להלן מא מו) ויוסף בן שלשים שנה וגו' , ושבע שנים שובע ושנתים רעב הרי עשרים ושתים, וכתיב ימי שני מגורי שלשים ומאת שנה נמצא יעקב במכירתו מאה ושמונה) :
@112 **עדה בת אילון.** היא (לעיל כו לד) בשמת בת אילון, ונקראת בשמת על שם שהיתה מקטרת בשמים לעבודה זרה: **אהליבמה.** היא יהודית, והוא כנה שמה יהודית לומר שהיא כופרת בעבודה זרה כדי להטעות את אביו: **בת ענה בת צבעון.** אם בת ענה לא בת צבעון, ענה בנו של צבעון, שנאמר (פסוק כד) ואלה בני צבעון ואיה וענה, מלמד שבא צבעון על כלתו אשת ענה ויצאת אהליבמה מבין שניהם והודיעך הכתוב שכלן בני ממזרות היו:
@113 **בשמת בת ישמעאל.** ולהלן קורא לה (כח ט) מחלת. מצינו באגדת מדרש ספר שמואל (פרק יז) שלשה מוחלין להן עונותיהם גר שנתגיר, והעולה לגדלה, והנושא אשה, ולמד הטעם מכאן, לכך נקראת מחלת שנמחלו עונותיה: **אחות נביות.** על שם שהוא השיאה לו משמת ישמעאל נקראת על שמו:
@115 **ואהליבמה ילדה** וגו' **.** קרח זה ממזר היה ובן אליפז היה, שבא על אשת אביו אל אהליבמה אשת עשו שהרי הוא מנוי עם (פסוק טז) אלופי אליפז בסוף הענין:
@116 **וילך אל ארץ.** לגור באשר ימצא:
@117 **ולא יכלה ארץ מגוריהם.** להספיק מרעה לבהמות שלהם. ומדרש אגדה (פסוק ו) מפני יעקב אחיו, מפני שטר חוב של גזרת (טו יג) כי גר יהיה זרעך, המטל על זרעו של יצחק, אמר אלך לי מכאן, אין לי חלק לא במתנה שנתנה לו הארץ הזאת, ולא בפרעון השטר. ומפני הבושה, שמכר בכורתו:
@119 **ואלה.** התולדות שהולידו בניו עכשיו משהלך לשעיר:
@122 **ותמנע היתה פילגש.** להודיע גדלתו של אברהם כמה היו תאבים לדבק בזרעו. תמנע זו בת אלופים היתה, שנאמר (פסוק כב) ואחות לוטן תמנע, ולוטן מאלופי יושבי שעיר היה, מן החורים שישבו בה לפנים, אמרה איני זוכה להנשא לך, הלואי ואהיה פילגש. ובדברי הימים מונה אותה (דברי הימים א' א לו) בבניו של אליפז, מלמד שבא על אשתו של שעיר ויצאה תמנע מביניהם, וכשגדלה נעשית פילגשו, וזהו ואחות לוטן תמנע, ולא מנאה עם בני שעיר שהיתה אחותו מן האם ולא מן האב:
@125 **אלה אלופי בני עשו.** ראשי משפחות:
@130 **ישבי הארץ.** שהיו יושביה קודם שבא עשו לשם. ורבותינו דרשו שהיו בקיאין בישובה של ארץ, מלא קנה זה לזיתים מלא קנה זה לגפנים, שהיו טועמין העפר ויודעים אי זו נטיעה ראויה לה:
@134 **ואיה וענה.** וי''ו יתרה, והוא כמו איה וענה, והרבה יש במקרא (דניאל ח יג) תת וקדש וצבא מרמס, (תהלים עו ז) נרדם ורכב וסוס: **הוא ענה.** האמור למעלה (פסוק כ) שהוא אחיו של צבעון וכאן הוא קורא אותו בנו, מלמד שבא צבעון על אמו והוליד את ענה: **את הימם.** פרדים, הרביע חמור על סוס נקבה וילדה פרד, והוא היה ממזר והביא פסולין לעולם. ולמה נקרא שמם ימים, שאימתן מטלת על הבריות, דאמר רבי חנינא מימי לא שאלני אדם על מכת פרדה לבנה וחיה (והלא קא חזינן דחיה, אל תקרי וחיה אלא וחיתה, כי המכה לא תרפא לעולם) . ולא הזקק לכתוב לנו משפחות החורי אלא מפני תמנע, ולהודיע גדלת זרע אברהם, כמו שפרשתי למעלה (פסוק יב) :
@141 **ואלה המלכים** וגו' **.** שמנה היו וכנגדן העמיד יעקב ובטל מלכות עשו בימיהם, ואלו הן שאול, ואיש בשת, דוד, ושלמה, רחבעם, אביה, אסא, יהושפט. ובימי יורם בנו כתיב (מ''ב ח כ) בימיו פשע אדום מתחת יד יהודה וימלכו עליהם מלך, ובימי שאול כתיב (מ''א כב מח) ומלך אין באדום נצב מלך:
@143 **יובב בן זרח מבצרה.** בצרה מערי מואב היא, שנאמר (ירמיה מח כד) ועל קריות ועל בצרה וגו' , ולפי שהעמידה מלך לאדום, עתידה ללקות עמהם, שנאמר (ישעיה לד ו) כי זבח לה' בבצרה:
@145 **המכה את מדין בשדה מואב.** שבא מדין על מואב למלחמה, והלך מלך אדום לעזור את מואב. ומכאן אנו למדים שהיו מדין ומואב מריבים זה עם זה, ובימי בלעם עשו שלום להתקשר על ישראל:
@149 **בת מי זהב.** שהיה אומר מהו זהב, עשיר היה ואין זהב חשוב בעיניו לכלום:
@150 **ואלה שמות אלופי עשו.** שנקרא על שם מדינותיהם לאחר שמת הדר ופסקה מהם מלכות. והראשונים הנזכרים למעלה, הם שמות תולדותם, וכן מפורש בדברי הימים (דברי הימים א' א נא) וימת הדד ויהיו אלופי אדום אלוף תמנע וגו' :
@153 **מגדיאל.** היא רומי:

@1 **אל עשו אחיו ארצה שעיר** . בעבור היות נגב ארץ ישראל על ידי אדום ואביו יושב בארץ הנגב יש לו לעבור דרך אדום או קרוב משם על כן פחד אולי ישמע עשו והקדים לשלוח אליו מלאכים לארצו וכבר תפסוהו החכמים על זה אמרו בבראשית רבה (עה ג) מחזיק באזני כלב וגו' (משלי כו יז) אמר לו הקב"ה לדרכו היה מהלך והיית משלח אצלו ואומר לו כה אמר עבדך יעקב ועל דעתי גם זה ירמוז כי אנחנו התחלנו נפילתנו ביד אדום כי מלכי בית שני באו בברית עם הרומיים (ספר החשמונאים א ח) ומהם שבאו ברומה (כך כותב רבינו בויקרא כו טז) והיא היתה סבת נפילתם בידם וזה מוזכר בדברי רבותינו ומפורסם בספרים (יוסיפון פרק סה)
@2 **כה תאמרון לאדני לעשו כה אמר עבדך יעקב** . צוה אותם שיאמרו לאדני לעשו אנחנו שלו או שלוחים אליו ולאמר לו כה אמר עבדך יעקב עם לבן גרתי ודומה לו בפרשה (להלן פסוק יח) למי אתה או שקראו יעקב בפניהם אדני עשו להזהירם שלא יזכירוהו אפילו שלא בפניו רק דרך כבוד בראותם כי אדונם קורא אותו אדני ודע כי הכבוד הזה שהיה יעקב עושה לאחיו בפחדתו לאמר אדני ועבדך בעבור כי המנהג בצעיר לתת מעלה וכבוד אל הבכור כאלו הוא אביו כאשר רמזה לנו גם התורה לרבות אחיך הגדול והנה יעקב לקח בכורתו ואת ברכתו ועשו שוטם אותו עליהם ועתה היה מראה לו כאלו אין המכירה ההיא אצלו כלום וכי הוא נוהג בו כבכור ואב להוציא את המשטמה מלבו
@3 **ואשלחה להגיד לאדני** . להודיע שאני בא אליך למצא חן בעיניך שאני שלם עמך ומבקש אהבתך לשון רש"י רצה לומר שאינו מוסב למעלה אבל יאמר ואשלחה להגיד לאדני כי אני בא למצוא חן בעיניך ולעשות ככל אשר יצוה אדני ויותר נכון שיוסב למעלה ואשלחה להגיד לאדני שיש לי עושר ונכסים וכבוד לעשות בו חפצך ורצונך ירמוז שישלח לו דורון מהם או שיקח הוא משלו מה שיחפוץ וכן אמר (להלן לג ח) מי לך כל המחנה הזה אשר פגשתי ויאמר למצא חן בעיני אדני
@4 **וישובו המלאכים אל יעקב לאמר** . השלוחים האלה עשו שליחותם אבל לא סיפר הכתוב זה כי אין צורך וטעם וגם הולך לקראתך לאמר כאשר אתה הולך לקראתו כן הוא הולך לקראתך ומהר תפגשו זה בזה
@5 **ויירא יעקב מאד** . בעבור שאמרו לו כי יצא עשו מעירו והוא בא לקראת יעקב ועוד שלקח עמו אנשים רבים ארבע מאות היה ירא לנפשו מאד כי אמר לא לקח כל אלה רק להלחם בי והנראה בעיני בענין הזה כי עשו לא קבל השלוחים כהוגן ולא השגיח עליהם ואולי לא היו לפניו כי לא נתן רשות שיבאו לפניו וידברו עמו כלל כי היה הכתוב מספר ששאל להם מה שלום אחי ומה ענינו ועניני ביתו ובניו וקראו לו בשלומו ואמרו לו כי אני הולך לקראתו לראותו והם היו מגידים כן ליעקב והכתוב לא סיפר שיאמרו השליחים דבר בשם עשו אבל עברתו שמורה בלבו ולעשות לו רעה היה הולך בחיל הזה והנה השלוחים חקרו במחנה וידעו כי הוא הולך לקראת יעקב וזה טעם "וגם" כי אמרו באנו אל אחיך אל עשו ולא ענה אותנו דבר ולא שלח לך דברי שלום וגם הולך לקראתך בזרוע וחיל ולכך הוסיף לו פחד על פחדו ויירא יעקב מאד ויצר לו וכך אמרו רבותינו (ב"ר עה ז) כי השלוחים הכירו בו שנאה אמרו באנו אל אחיך אל עשו אתה נוהג בו כאח והוא נוהג עמך כעשו אבל בסוף כאשר ראה הכבוד הגדול שעשה לו יעקב ואשר השפיל עצמו לפניו שהשתחוה ארצה שבע פעמים מרחוק עד גשתו אליו נכמרו רחמיו וחשב כי הוא מודה בבכורתו ובגדולתו עליו כאשר פירשתי (לעיל בפסוק ה) והתנחם בזה כי הלבבות לה' המה לכל אשר יחפוץ יטה אותם
@6 **והיה המחנה הנשאר לפליטה** . על דרך הפשט אמר זה באולי כי אמר אולי ינצל המחנה האחד כי בהכותו האחד יברחו האחרים או תשוב חמתו או תבא להם הצלה מאת השם וכן אמרו בבראשית רבה (עו ג) למדתך תורה דרך ארץ לא יניח אדם כל ממונו בזוית אחת ורש"י כתב והיה המחנה הנשאר לפליטה על כרחו כי אלחם עמו התקין עצמו לשלשה דברים לתפלה ולדורון ולמלחמה וראיתי במדרש (קה"ר ט יח) מה עשה זיינם מבפנים והלבישם בגדים לבנים מבחוץ והתקין עצמו לשלשה דברים וכן עיקר והכונה בזה כי יעקב יודע שאין זרעו כלו נופל ביד עשו אם כן ינצל המחנה האחד על כל פנים וגם זה ירמוז שלא יגזרו עלינו בני עשו למחות את שמנו אבל יעשו רעות עם קצתנו בקצת הארצות שלהם מלך אחד מהם גוזר בארצו על ממוננו או על גופנו ומלך אחר מרחם במקומו ומציל הפלטים וכך אמרו בבראשית רבה (עו ג) אם יבא עשו אל המחנה האחת והכהו אלו אחינו שבדרום והיה המחנה הנשאר לפלטה אלו אחינו שבגולה ראו כי גם לדורות תרמוז זאת הפרשה
@8 **קטנתי מכל החסדים ומכל האמת** . נתמעטו זכיותי על ידי חסדים ואמת שעשית עמי לכך אני ירא שמא משהבטחתני נתקלקלתי בחטא ויגרום לי להמסר ביד עשו לשון רש"י ואיננו נכון בלשון הכתוב ועוד כי אמר אחרי כן ואתה אמרת היטב איטיב עמך ושמתי את זרעך כחול הים ומה יועיל הבטחון ההוא אם גרם החטא אחר כך ועוד כי יעקב הזכיר שתי הבטחות שהבטיחו הקב"ה בבית אל ובחרן ואמר תחלה מה שנאמר לו בחרן ה' האומר אלי שוב לארצך ולמולדתך ואיטיבה עמך והוא שנאמר לו בצאתו מבית לבן (לעיל לא ג) שוב אל ארץ אבותיך ולמולדתך ואהיה עמך והנה אחרי כן לא היטיב לו בכל החסדים ובכל האמת האלה שיתמעטו זכיותיו על ידיהם אבל "קטונתי" לומר כי קטון הוא מהיותו ראוי לכל החסדים שעשה עמו וכן מי יקום יעקב כי קטון הוא (עמוס ז ב) מהיותו יכול לסבול כל הנגזר עליו וכן אמרו בבראשית רבה (עו ח) קטונתי רבי אבא אמר איני כדאי והחסדים הם הטובות שעשה עמו בלא נדר והאמת הטובה אשר הבטיחו ואימת לו הבטחתו יאמר שאיננו ראוי שיבטיחנו ויעשה לו אותן טובות שהבטיחו בהן ולא לטובות אחרות רבות שעשה עמו ולא הבינותי דעת אונקלוס שתרגם מכל חסדין ומכל טבון והוא רגיל לתרגם חסד ואמת "טיבו וקשוט" (לעיל כד מט להלן מז כט) ואולי עושה חסדים הצלתו אשר הצילו פעמים רבות מכל צרותיו ועשה אמת כל הטוב הזה שהיה לו כי נתן לו בנים ובנות ועושר ונכסים וכבוד והנכון בעיני כי החסדים הקיימים יקראו אמת כי היא מגזרת אמנה כטעם ונאמן ביתך וממלכתך עד עולם ( ז טז) ענין קיום לחמו נתן מימיו נאמנים (ישעיהו לג טז) כאשר אמר היו תהיה לי כמו אכזב מים לא נאמנו (ירמיהו טו יח)
@9 **והכני אם על בנים** . פירשו בו (הראב"ע) והכני והכה אם על בנים וכן רבים
@10 **ואתה אמרת היטב איטיב עמך** . אף על פי שהיתה פחדתו פן יגרום החטא אמר עשית עמדי חסדים גדולים שלא הייתי ראוי להם כל שכן שיש לעשות עמי חנם החסד הזה אשר הבטחתני עליו שתיטיב לי ותרבה את זרעי ואין חטאי ראוי למנוע ממני הטובה אשר הבטחתני בה כי גם מתחילה לא הייתי ראוי לה אם עונות תשמור לי ולא הבטחתני עליה בעבור מעשי רק בחסדיך הרבים ויש אומרים כי יעקב היה חומל על בניו ועל ביתו פן יכה אותם עשו כי לא היה יודע בהבטחת והיה זרעך כעפר הארץ אם על אלה או על אחרים כי יתכן שימלט הוא לבדו וירבה עוד זרעו ואיננו נכון בעיני כי אם היתה זאת מחשבתו איך אמר בתפלתו ואתה אמרת היטב איטיב עמך ושמתי את זרעך ועוד כי שם נאמר לו והנה אנכי עמך ושמרתיך בכל אשר תלך והשיבותיך אל האדמה הזאת כי לא אעזבך ואם יהיו בניו נופלים בחרב אחיו אין ההבטחה הזאת קיימת ולזה ירמוז באמרו היטב איטיב עמך וכן ואיטיבה עמך כי כל זה ממה שנאמר לו (לעיל לא ג) ואהיה עמך אבל הכל מיראת חטא כי דרך הצדיקים לירא תמיד והיה מתירא אולי אפילו משיצא משם חטא בבואו בברית עם לבן עובד עבודה זרה או בדבר אחר ושגיאות מי יבין
@11 **מן הבא בידו מנחה** . יאמר כי עשה מנחה מאשר עמו כי עשרו היה צאן ובקר ומהם שלח כי בדרך היה ואיננו מקום לשלוח לו כלי כסף וכלי זהב ומגדנות
@14 **ורוח תשימו בין עדר** . כדי להשביע עינו של אותו הרשע ולתווהו על הדורון וסברו בבראשית רבה (עה יג) שיש בזה רמז אמר יעקב לפני הקב"ה רבונו של עולם אם יהיו צרות באות על בני לא תביא אותן זו אחר זו אלא הרוח להם מצרותיהם עשה רמז שיהיו המסים והארנוניות שיגבו בני עשו מזרעו ברוח והפרש בין זו לזו
@18 **אכפרה פניו במנחה** . אבטל רוגזיה וכן וכפר בריתכם את מות (ישעיהו כח יח) לא תוכלי כפרה (שם מז יא) ונראה בעיני שכל כפרה שאצל חטא ועון ואצל פנים כלם לשון קנוח והעברה הן ולשון ארמית הוא בהרבה מקומות בעי לכפורי ידיה (גיטין נו) וגם בלשון מקרא נקראים המזרקים כפורי זהב (עזרא א י) על שם שבהם מקנח ידיו בשפת המזרק לשון רבינו שלמה וכן אמר אונקלוס אנחיניה לרוגזיה ואם כן יהיה פירושו כי חשב יעקב בלבו אכפרה פניו והכתוב מגיד לנו זה כי איננו ראוי שיאמרו השלוחים לעשות ככה וכך פירש רבי אברהם ואיננו ישר בעיני שיצטרך הכתוב להגיד לנו עתה מחשבתו זאת והיא ידועה בכל שולחי מנחה ועוד שאם כן היה ראוי שיזכיר הכתוב זה בתחלה והנה גם הוא אחרינו כי חשב אכפרה פניו כי עתה לא הוסיף על הצואה ההיא אבל הנכון כי עתה הוסיף לפרש להם שיאמרו הנה גם הוא אחרינו בלשון כבוד כלשון זה גם הנה עבדך יעקב אחרינו והקדים אותנו לפניו לתת כופר נפשו על ראותו פני כבודך במנחה הזאת כאשר יתנו העבדים כפרם בתת להם רשות לראות פני המלך ואחרי כן אראה פניו כי אולי ישא פני ויכבדני להיותי מרואי פני המלך וזה דרך מעלה מיראתו ממנו ובא אכפרה פניו כדרך ואיש חכם יכפרנה (משלי טז יד) יתן כפר על החמה ולשון קנוח בכפור איננו לשון קדש רק לשון ארמית וכן כפורי זהב שם המזרקים בבבל כי לעולם לא תבא כפרה בחטא אבל יאמר לכפר על נפשותיכם (שמות ל טו) לכפר עליו ונסלח לו (במדבר טו כח) על נפשו ויאמר אכפרה בעד חטאתכם (שמות לב ל) וכולן מלשון ונתנו איש כופר נפשו (שם ל יב) שהוא פדיון
@19 **והוא לן בלילה ההוא במחנה** . יאמר שלא בא באהלו בלילה ההוא אבל לן במחנה עם עבדיו ועם הרועים בצאן ערוך כאיש מלחמה פן יבא אחיו בלילה ויכה בו
@20 **ויקח את שתי נשיו ואת שתי שפחותיו** . אין מוקדם ומאוחר בפסוק הזה להצלה אבל אמר שאסף נשיו ושפחותיו וילדיו אל שפת הנחל ועבר הוא לבדו את מעבר יבוק לראות אם גבהו המים ושב ולקחם עמו כולם כאחד ויעבירם את הנחל ואחרי כן ויעבר את אשר לו מקנהו ורכושו
@20 "ויותר יעקב לבדו" - ששכח פכים קטנים וחזר עליהן לשון רש"י ועל דרך הפשט ויקחם ויעבירם את הנחל העבירם עמו ויעבר את אשר לו בצווי כי חזר וצוה שיעברו לפניו ונשאר הוא אחריהם
@20 "ויאבק איש עמו" - ויתעפר כך פירשו מנחם לשון אבק שמעלין אבק ברגליהם ולי נראה לשון ויתקשר ולשון ארמי הוא בתר דאביקו ביה (סנהדרין סג) ואביקו ליה מיבק (מנחות מב) זה לשון רש"י ואביקה בלשון חכמים חביקה שמשו בה הרבה אבקתא אית בה (מכות כג) דרגש עיולי ואפוקי באבקתא (נדרים נו) וכן אבוקה בלשונם בעבור היותה מעצים דקים חגורים וקשורים יחד כי החי"ת תכבד בלשונם והקלו אותה לאל"ף ופעמים רבים יבליעו החי"ת תותך (חולין ז) במקום תחותך (זבחים נד) מסותא (ב"מ ו) במקום מסחותא (קדושין לג) אסיתא חסיתא (שבת עז) ואפשר שיהיה ויאבק ויחבק כמו ויחבקהו (להלן לג ד) כי אולי כן הלשון ומצינו ברודים אמוצים (זכריה ו ג) כמו חמוצים מלשון חמוץ בגדים (ישעיהו סג א) ואמרו המפרשים (הרד"ק) כי וארוזים במרכולתך (יחזקאל כז כד) כמו וחרוזים מן צוארך בחרוזים (שיר השירים א י) וכן אמרו במלת ותאלצהו (שופטים טז טז) שהוא כמו ותחלצהו מהופך מן ותלחצהו ושמא הוא דעת אונקלוס שאמר ואשתדל וכך תרגם וכי יפתה (שמות כב טו) ארי ישדל יחבק וינשק שהוא דרך הפתוי או שלא נזדמן לו לשון ועשאו ענין תחבולה כי כל השתדלות תחבולה וצדוד ענין ובבראשית רבה (עז ג) מי נתמלא אבק האיש שהיה עמו כדברי מנחם והוא הנכון
@23 **וירא כי לא יכל לו** . מלאכיו גבורי כח עושי דברו ועל כן לא יכול לו המלאך להזיקו כי לא הורשה רק במה שעשה עמו להקע כף ירכו ואמרו בבראשית רבה (עז ג) נגע בכל הצדיקים שעתידין להיות ממנו זה דורו של שמד והענין כי המאורע כלו רמז לדורותיו שיהיה דור בזרעו של יעקב יתגבר עשו עליהם עד שיהיה קרוב לקעקע ביצתן והיה זה דור אחד בימי חכמי המשנה כדור של רבי יהודה בן בבא וחביריו כמו שאמרו (שיר השירים ב ז) אמר רבי חייא בר אבא אם יאמר לי אדם תן נפשך על קדושת שמו של הקב"ה אני נותן ובלבד שיהרגוני מיד אבל בדורו של שמד איני יכול לסבול ומה היו עושים בדורו של שמד היו מביאין כדוריות של ברזל ומלבנין אותן באור ונותנין אותן תחת שיחיהן ומשיאין נפשותיהן מהן ויש דורות אחרים שעשו עמנו כזה ויותר רע מזה והכל סבלנו ועבר עלינו כמו שרמז ויבא יעקב שלם
@27 **למה זה תשאל לשמי** . אמר אין לך בידיעת שמי תועלת כי אין הכח והיכולת בלתי לה' לבדו אם תקראני לא אענך וגם מצרתך לא אושיעך אבל עתה אברך אותך כי כן צוותי ולא פירש הכתוב הברכה והקרוב מה שאמרו רבותינו (במדרש אגדה ובזוה"ק תולדות קמד) שהודה לו על כל הברכות שם במקום ההוא על כרחו כי לא רצה יעקב להמתין לו עד בית אל
@35 **מי אלה לך** . שאל על הנשים ועל הילדים וענה הילדים אשר חנן אלהים את עבדך דרך מוסר כי לא רצה לומר שהם נשיו והבין עשו שהן אמות הילדים
@38 **מי לך כל המחנה הזה אשר פגשתי** . הנה עבדי יעקב עשו כאשר צוה אותם ולא רצה לקבל מהם או שהוא בגאותו ועברתו לא דבר עמם ולא שאלם למי אתה ואנה תלך והם יראו מגשת אליו ואמר עתה מי לך כל המחנה הזה כי חשב שהם ליעקב מדברי המלאכים הראשונים או שאלה השלוחים הגידו כן במחנה עשו או שאין אדם אחד בדרך ההוא להיות לו כן וטעם מי לך כל המחנה הזה כלומר מי זה לך שתשלח לו כל אלה כלומר מי הוא הגדול אצלך שתשלח לו כל אלה והוא ענהו למצוא חן בעיני אדוני כי אתה הגדול והאדון בעיני
@40 **כי על כן ראיתי פניך** . אמר לו תקח מנחתי מידי בעבור שראיתי פניך שהם לי כראות פני אלהים ותרצני בקבלת המנחה כאשר האלהים רוצה את יראיו בקבלת מנחתם וקרבנם כענין ונרצה לו (ויקרא א ד) עולותיכם וזבחיכם לרצון על מזבחי (ישעיהו נו ז) מלשון יהי רצוי אחיו (דברים לג כד) ואור פניך כי רציתם (תהלים מד ד) כי רצו עבדיך את אבניה (שם קב טו) כולם ענין חפץ וחשק בדבר ורש"י כתב על שנתרצית למחול לי על סורחני ותרצני נתפייסת לי וכבר אמרתי (לעיל לב כא) שאיננו טוב שיהיה לו מזכיר עון
@41 **קח נא את ברכתי** . המנחה וכן עשו אתי ברכה (מלכים ב יח לא) השיבו לי מנחה וכן קח נא ברכה מאת עבדך (שם ה טו) ויקראו המנחה שישלח האדם לרצונו ברכה כי הוא שולח מאשר ברך אותו השם כענין אשר ברכך ה' אלהיך תתן לו (דברים טו יד) כאשר אמר למעלה (לב יד) מן הבא בידו והמנחה אשר התנו בה למלך בדבר ידוע תקרא מס
@43 **ומתו כל הצאן** . דרך חמלה שהיה לו לומר "ומתו כלם" אבל לא יאמר כן על הילדים וגם לא רצה לומר "ומתו" סתם על הבקר ועל הצאן כי יחמול על הילדים שלא יהיו במשמע ולא רצה להאריך "ומתו כל הצאן והבקר" או יהיה פירושו כי הילדים רכים ויעפו נערים וייגעו ולא ירצו ללכת והצאן והבקר עלות ואם ידחקום ימותו הצאן שהם בהמה דקה כי הבקר לא ימות אבל יזיק להם
@44 **עד אשר אבא אל אדוני שעירה** . היה ליעקב בשובו אל ארצו דרך בארץ שעיר והנה אמר לו עשו ואלכה לנגדך שלא יפרד ממנו עד שובו אל אביו לעשות לו כבוד בבואו אל ארצו ויעקב אמר אני אלך לאטי ואדני ישוב אל עיר ממשלתו ואם אשוב דרך עירו יכבדני וילך עמי כאשר יחפוץ ולא היה זה נדר ממנו שיבא אליו שאין עשו צריך לו ורבותינו אמרו (ע"ז כה) עוד שלא היה בדעת יעקב לשוב דרך שעיר ורצונו היה להתרחק ממנו כאשר יוכל אבל הרחיב לו את הדרך וגם זו עצת חכמה ועוד להם מדרש אחר (ב"ר עח יד) שיקים דברו לימות המשיח שנאמר (עובדיה א כא) ועלו מושיעים בהר ציון לשפוט את הר עשו יאמר כי המושיעים אשר בהר ציון יעלו לשפוט את הר עשו
@45 **למה זה אמצא חן בעיני אדני** . למה זה תעשה לי טובה שאיני צריך לה אמצא חן בעיניך ולא תשלם עתה שום גמול לשון רש"י והכונה ביעקב כי לא היה חפץ בהם ובחבורתם כלל וכל שכן שהיה בדעתו ללכת דרך אחרת ורבותינו ראו עוד בזה עצה אמרו (ב"ר עח טו) רבי ינאי כד הוה סליק למלכותא הוה מסתכל בהדא פרשתא ולא הוה נסיב עמיה רומאין חד זמן לא איסתכל בה ונסיב עמיה רומאין ולא הגיעו לעכו עד שמכר פינס שלו מפני שהיתה קבלה בידם שזו פרשת גלות כשהיה בא ברומה בחצר מלכי אדום על עסקי הצבור היה מסתכל בפרשה זו ללכת אחרי עצת הזקן החכם כי ממנו יראו הדורות וכן יעשו ולא היה מקבל חברת אנשי רומי ללותו שאין מקרבין אלא להנאת עצמן ומפקירין ממונו של אדם
@47 **ויבן לו בית** . יתכן כי היה המקום מקום אין שם עיר והוצרך לבנות לו בית ולעשות סוכות או ויבן לו בית שבנה לו בית גדול ובו מגדל עז להשגב מפני עשו
@48 **ויבא יעקב שלם מפדן ארם** . כאומר לחברו יצא פלוני מבין שני אריות ובא שלם אף כאן ויבא יעקב שלם מלבן ומעשו זה לשון רש"י אבל רבי אברהם פירש שבא בשלום ולא אירע לו שום מאורע כי עתה יחל לספר מאורע דינה ולפי דעתי אמר הכתוב כן כי בסוכות היה מתפחד מעשו כי סכות בעבר הירדן מזרח במלכות סיחון אם הוא המוזכר בספר יהושע (יג כז) ואם הוא אחר הנה הוא יותר קרוב לשעיר ועד היותו בארץ כנען לא שקט לבו כי אז ידע שלא יגע בו כי אביו קרוב משם או שיעזרוהו אנשי הארץ כי אביו נשיא אלהים בתוכם או שזכות הארץ תצילהו ולכן אמר עתה שבא שלם אל ארץ מגורי אביו כי הצילו אלהים בדרך מכף כל אויביו ואמרו בבראשית רבה (עח טז) כל אותן החדשים שעשה יעקב אבינו בסוכות היה מכבד את עשו באותו הדורון כי היה מתירא ממנו שם ומשלח לו כאותו הדורון בכל חדש וחדש או פעם אחת בשנה
@48 "ויחן את פני העיר" - לא רצה להיות אכסנאי בעיר אבל רצה שתהיה תחילת ביאתו בארץ בתוך שלו ולכן חנה בשדה וקנה המקום וזה להחזיק בארץ והמעשה הזה היה רמז כי המקום ההוא יכבש לפניו תחילה טרם הורישו יושבי הארץ מפני זרעו כאשר פרשתי באברהם (לעיל יב ו) ורבותינו אמרו (ב"ר עט ו) נכנס עם דמדומי חמה וקבע לו תחומין ועל דעתם לא היה בכוונה ממנו אבל על כל פנים היה המאורע לרמוז על העתיד שאמרנו אבל רבי אברהם אמר כי הזכיר הכתוב זה להודיע כי מעלה גדולה לארץ ישראל ומי שיש לו חלק בה חשוב הוא כחלק העולם הבא
@50 **ויקרא לו אל אלהי ישראל** . לא שהמזבח קרוי אלהי ישראל אלא על שם שהיה הקב"ה עמו להצילו קרא שם המזבח על שם הנס להיות שבחו של הקב"ה נזכר בקריאת המזבח כלומר מי שהוא אל הוא אלהים לי ששמי ישראל וכן מצינו במשה ויקרא שמו ה' נסי (שמות יז טו) לא שהמזבח קרוי ה' אלא על שם הנס קרא שם המזבח להזכיר שבחו של הקב"ה ה' הוא נסי ורבותינו דרשו (מגילה יח) שהקב"ה קראו ליעקב אל ודברי תורה כפטיש יפוצץ סלע מתחלקין לכמה טעמים ואני לישב פשוטו באתי כל זה לשון רש"י והנה צדקו דברי הרב בפשוטו של מקרא ויהי טעם "לו" כטעם קרא לו בנימין (להלן לה יח) וקורא לך גודר פרץ (ישעיהו נח יב) ודע כי המנהג הזה בישראל כן שיקראו השמות בשבחי האל כמו צוריאל (במדבר ג לה) צורישדי (שם א ו) כי יגיד הקורא שהאל הוא צורו ושדי הוא צורו וכן עמנו אל (ישעיהו ז יד) וכן שם המשיח ה' צדקנו (ירמיהו לג טז) ושם ירושלים ה' שמה (יחזקאל מח לה) וכן יעשו בשמות מלאכים גבריאל (דניאל ח טז) מיכאל (שם ו כא) כי בעבור גדולת כחם יגידו בשמם כי הגבורה לאל ומי כמוהו אבל אונקלוס אמר ופלח עלוהי קדם אל אלהא דישראל ויהיה טעם "לו" כטעם בו כדרך כי בוחר אתה לבן ישי (שמואל א כ ל) והחזיק לו ( טו ה) למי מריבה (במדבר כ כד) או יאמר ויקרא אל אלהי ישראל וטעם "לו" כטעם אלכה לי אל הגדולים (ירמיהו ה ה) לך לך מארצך (לעיל יב א) ועל דרך האמת הוא כמדרש רבותינו שדרשו רבותינו במסכת מגלה (יח) מנין שקראו הקב"ה ליעקב אל שנאמר ויקרא לו אל אלהי ישראל ויש בענין הזה סוד גדול הזכירוהו עוד בבראשית רבה (עט ח) בלשון אחר אמר לו אתה אלוה בעליונים ואני אלוה בתחתונים ירמזו למה שהם אומרים תמיד שאיקונין של יעקב חקוקה בכסא הכבוד והכונה שהשכינה שורה בארץ ישראל והמשכיל יבין
@51 **וטעם בת לאה אשר ילדה ליעקב** . לומר שהיא אחות שמעון ולוי המקנאים ונוקמים נקמתה והזכיר אשר ילדה ליעקב כי כל האחים קנאו בה
@52 **וישכב אותה ויענה** . וישכב כדרכה ויענה שלא כדרכה (ב"ר פ ה) לשון רש"י אבל רבי אברהם אמר ויענה בעבור היותה בתולה ואין צורך כי כל ביאה באונסה תקרא ענוי וכן לא תתעמר בה תחת אשר עניתה (דברים כא יד) וכן ואת פלגשי ענו ותמת (שופטים כ ה) ויגיד הכתוב כי היתה אנוסה ולא נתרצית לנשיא הארץ לספר בשבחה
@57 **וכן לא יעשה** . לענות הבתולות שהאומות גדרו עצמן מן העריות מפני המבול לשון רש"י ולא ידעתי זה כי הכנענים שטופים בעריות ובבהמה ובזכור דכתיב (ויקרא יח כז) כי את כל התועבות האל עשו אנשי הארץ אשר לפניכם ולא התחילו בהן באותו הדור ובימי אברהם ויצחק היו יראים פן יהרגו אותן לקחת נשיהם אבל "וכן לא יעשה" נמשך עם בישראל כי נבלה עשה בישראל וכן לא יעשה בהם על כן אמר בישראל כי איננה נבלה בין הכנענים ואונקלוס אמר לא כשר לאיתעבדא לומר שהוא אסור ולכך היא נבלה בישראל
@62 **מהר** . פראנון מתן פרא פרנון והם כתובה ונכסי מלוג בלשון ירושלמי כלומר שיתן לה הוא משלו נכסים שיהיו שלה כנכסי בית אביה ויהיו אצלו כנכסי מלוג וטעם הפיוס הזה כדי שיתנו אותה לו לאשה ברצון כי הנערה לא היתה מתרצה אליו וצועקת ובוכה תמיד וזה טעם וידבר על לב הנערה ולכך אמר קח לי את הילדה הזאת לאשה שכבר היא בביתו ובידו ולא יירא מאחיה כי הוא נשיא הארץ ואיך יגזלוה ממנו להוציאה מביתו והחשק הגדול לשכם כי היתה הנערה יפת תאר מאד אבל לא סיפר הכתוב ביפיה כאשר עשה בשרה וברבקה וברחל כי לא ירצה להזכיר יפיה בהיותו אליה למכשול עון ובשבח הצדיקות דבר הכתוב ולא בזו וכן לא הזכיר מה נעשה בה אחרי כן ועל דרך הפשט עמדה עם אחיה צרורה באלמנות חיות כי היתה טמאה בעיניהם כדכתיב
@62 "אשר טמא את דינה אחותם" - ורבותינו נחלקו בה (ב"ר פ יא) והקרוב דברי האומר נטלה שמעון וקברה בארץ כנען והוא כמו שאמרנו כי היתה עמו בביתו כאלמנה וירדה עמהם למצרים ושם מתה ונקברה בארץ וקבורתה ידועה עד היום בקבלה והיא בעיר ארבאל עם קבר ניתאי הארבלי ויתכן כי העלה שמעון עצמותיה בחמלו עליה או שהעלו אותם ישראל עם עצמות אחיה כל השבטים כמו שהזכירו רבותינו (ב"ר ק יא)
@63 **ויענו בני יעקב את שכם ואת חמור אביו במרמה** . הנה חמור ושכם אל אביה ואל אחיה דברו אבל הזקן לא ענה אותם דבר כי בניו ידברו במקומו בענין הזה לכבודו כי בעבור היות הדבר להם לקלון לא ירצו שיפתח פיו לדבר בו כלל ויש כאן שאלה שהדבר נראה כי ברצון אביה ובעצתו ענו כי לפניו היו והוא היודע מענם כי במרמה ידברו ואם כן למה כעס ועוד שלא יתכן שיהיה רצונו להשיא בתו לכנעני אשר טמא אותה והנה כל האחים ענו המענה הזה במרמה ושמעון ולוי לבדם עשו המעשה והאב ארר אפם להם לבדם והתשובה כי המרמה היתה באמרם להמול להם כל זכר כי חשבו שלא יעשו כן בני העיר ואם אולי ישמעו לנשיאם ויהיו כלם נמולים יבואו ביום השלישי בהיותם כואבים ויקחו את בתם מבית שכם וזאת עצת כל האחים וברשות אביהם ושמעון ולוי רצו להנקם מהם והרגו כל אנשי העיר ויתכן שהיה הכעס ליעקב שארר אפם על שהרגו אנשי העיר אשר לא חטאו לו והראוי להם שיהרגו שכם לבדו וזהו מה שאמר הכתוב ויענו בני יעקב את שכם ואת חמור אביו במרמה וידברו אשר טמא את דינה אחותם כי כולם הסכימו לדבר לו במרמה בעבור הנבלה שעשה להם ורבים ישאלו ואיך עשו בני יעקב הצדיקים המעשה הזה לשפוך דם נקי והרב השיב בספר שופטים (רמב"ם הלכות מלכים פי"ד ה"ט) ואמר שבני נח מצווים על הדינים והוא להושיב דיינין בכל פלך ופלך לדון בשש מצות שלהן ובן נח שעבר על אחת מהן הוא נהרג בסייף ראה אחד שעבר על אחת מהן ולא דנוהו להרגו הרי זה הרואה יהרג בסייף ומפני זה נתחייבו כל בעלי שכם הריגה שהרי שכם גזל והם ראו וידעו ולא דנוהו ואין דברים הללו נכונים בעיני שאם כן היה יעקב אבינו חייב להיות קודם וזוכה במיתתם ואם פחד מהם למה כעס על בניו וארר אפם אחר כמה זמנים וענש אותם וחלקם והפיצם והלא הם זכו ועשו מצוה ובטחו באלהים והצילם ועל דעתי הדינין שמנו לבני נח בשבע מצות שלהם אינם להושיב דיינין בכל פלך ופלך בלבד אבל צוה אותם בדיני גנבה ואונאה ועושק ושכר שכיר ודיני השומרים ואונס ומפתה ואבות נזיקין וחובל בחבירו ודיני מלוה ולוה ודיני מקח וממכר וכיוצא בהן כענין הדינין שנצטוו ישראל ונהרג עליהן אם גנב ועשק או אנס ופתה בתו של חבירו או שהדליק גדישו וחבל בו וכיוצא בהן ומכלל המצוה הזאת שיושיבו דיינין גם בכל עיר ועיר כישראל ואם לא עשו כן אינן נהרגין שזו מצות עשה בהם ולא אמרו (סנהדרין נז) אלא אזהרה שלהן זו היא מיתתן ולא תיקרא אזהרה אלא המניעה בלאו וכן דרך הגמרא בסנהדרין (נט) ובירושלמי אמרו בדינין של נח הטה דינו נהרג לקח שחד נהרג בדיני ישראל כל דין שאתה יודע שאתה שלם ממנו אי אתה רשאי לברוח ממנו וכל שאתה יודע שאי אתה שלם ממנו אתה רשאי לברוח ממנו אבל בדיניהם אף על פי שאתה יודע שאתה שלם ממנו אתה רשאי לברוח ממנו נראה מכאן שרשאי הגוי לאמר לבעלי הדין איני נזקק לכם כי תוספת היא בישראל לא תגורו מפני איש (דברים א יז) אל תכניס דבריך מפני איש (סנהדרין ו) וכל שכן שלא יהרג כשלא יעשה עצמו קצין שוטר ומושל לשפוט את אדוניו ומה יבקש בהן הרב חיוב וכי אנשי שכם וכל שבעה עממין לא עובדי עבודה זרה ומגלה עריות ועושים כל תועבות השם היו והכתוב צווח עליהן בכמה מקומות (דברים יב ב) על ההרים הרמים ועל הגבעות ותחת כל עץ רענן וגו' לא תלמד לעשות וכו' (שם יח ט) ובגלוי עריות כי את כל התועבות האל עשו וכו' (ויקרא יח כז) אלא שאין הדבר מסור ליעקב ובניו לעשות בהם הדין אבל ענין שכם כי בני יעקב בעבור שהיו אנשי שכם רשעים ודמם חשוב להם כמים רצו להנקם מהם בחרב נוקמת והרגו המלך וכל אנשי עירו כי עבדיו הם וסרים אל משמעתו ואין הברית אשר נמולו נחשב בעיניהם למאומה כי היה להחניף לאדוניהם ויעקב אמר להם בכאן כי הביאוהו בסכנה שנאמר עכרתם אותי להבאישני ושם ארר אפם כי עשו חמס לאנשי העיר שאמרו להם במעמדו וישבנו אתכם והיינו לעם אחד והם היו בוחרים בהם ובעטו בדבורם ואולי ישובו אל ה' והרגו אותם חנם כי לא הרעו להם כלל וזהו שאמר כלי חמס מכרותיהם (להלן מט ה) ואם נאמין בספר "מלחמות בני יעקב" (הוא ספר הישר) בא להם פחד אביהם כי נאספו שכני שכם ועשו עמהם שלש מלחמות גדולות ולולי אביהם שחגר גם הוא כלי מלחמתו ונלחם בם היו בסכנה כאשר יספר בספר ההוא ורבותינו (ב"ר פ י) הזכירו מזה בפסוק אשר לקחתי מיד האמורי בחרבי ובקשתי (להלן מח כב) אמרו נתכנסו כל סביבותיהם להזדווג להם חגר יעקב כלי מלחמה כנגדן כמו שכתב רש"י שם אבל הכתוב יקצר בזה כי היה נס נסתר כי אנשים גבורים היו וכאלו זרועם הושיעה למו כאשר קצר הכתוב בענין אברהם באור כשדים ולא הזכיר מלחמת עשו עם החורי כלל אבל הזכיר בכאן כי היה חתת אלהים על הערים אשר סביבותיהם ולא נאספו כולם לרדוף אחרי בני יעקב כי היו נופלים עליהם כחול אשר על שפת הים לרוב וזה טעם "חתת אלהים" כי נפלה עליהם אימתה ופחד מן הגבורה אשר ראו במלחמה ולכך אמר (להלן לה ו) ויבא יעקב לוזה הוא וכל העם אשר עמו להודיע שלא נפקד מהם ולא מעבדיהם איש במלחמה
@71 **שלמים הם אתנו** . היו אנשי העיר חושבים שהיו שונאים אותם כי ראו אותם עצבים ויחר להם מאד ואולי היו נשמרים מהם ונותנים בעירם בריח ודלתים כי גבורים המה ואנשי חיל למלחמה ועתה אמרו להם אל תפחדו ואל תתרחקו מהם כי בלב שלם הם אתנו
@73 **וטעם מקניהם וקנינם וכל בהמתם** . כי הבהמות אשר בעדרים בשדה הם יקראו מקנה בעבור שהם עיקר קנין האדם בין טמאות בין טהורות כענין שכתוב (שמות ט ג) הנה יד ה' הויה במקנך אשר בשדה בסוסים בחמורים בגמלים בבקר ובצאן ואשר אינם עדר כגון בהמות יחידות בבית אין שמם מקנה ויכנסו בכלל "וכל בהמתם" או הוא כפל הלשון לחזוק כלומר וכל בהמתם אשר הנם רבות מאד
@82 **ושב שם ועשה שם מזבח** . לא ידעתי מהו ושב שם ויתכן שצוהו לשבת שם תחלה ואחר כן יעשה המזבח להטהר מעבודה זרה או מן החללים שהרגו כענין ואתם חנו מחוץ למחנה שבעת ימים (במדבר לא יט) כי לא צוו עדיין במי חטאת ויעקב נזדרז במצוה להטהר טרם בואו שם או שיהיה ונקומה ונעלה בית אל מוקדם במעשה ואולי צוה ושב שם לפנות מחשבתו לדבקה באל
@85 **ויטמון אותם יעקב** . עבודה זרה ומשמשיה אינן מן הנקברים אבל צריך שיהא מפרר וזורה לרוח או מטיל לים (ע"ז מג) והנראה אלי כי בני יעקב לא לקחו עבודה זרה ומשמשיה משכם עד שנתבטלה והותרה להם שהעכו"ם מבטל עבודה זרה בעל כרחו (שם מג) והנה היא מותרת להם אבל יעקב צוה להסיר אותה לטהרת הקדש שיהיו ראויים לעבוד את השם ולהקריב לפניו קרבן כאשר צוה להם בטבילה וחלוף הבגדים והיה די להם בקבורה ולכן טמן אותם תחת האלה במקום שלא יעבד בו ולא יזרע
@89 **ותמת דבורה מינקת רבקה** . לא ידעתי למה נכנס הפסוק הזה בין "ויקרא למקום אל בית אל" ובין "וירא אלהים אל יעקב עוד" והפסיק בענין אחר שהיה בבת אחת ובמקום אחד כי יעקב בבאו לוזה היא בית אל בנה מזבח וקרא למקום אל בית אל ונראה לו האלהים שם ויברך אותו ולמה הושם הכתוב הזה בתוך ענין אחד והקרוב מה שאמרו רבותינו (ב"ר פא ה) שירמוז למיתת רבקה ולכן קרא שם המקום ההוא אלון בכות כי אין בכי ואנקה על המינקת הזקנה שיקרא שם המקום עליו אבל יעקב בכה והתאבל על אמו הצדקת אשר אהבתהו ושלחה אותו שם ולא זכתה לראותו בשובו ולכן נגלה אליו האלהים וברך אותו לנחמו כאשר עשה ליצחק אביו אחרי מות אברהם (לעיל כה יא) ובשניהם אמרו חכמים (סוטה יד) ברכת אבלים ברכו וסיוע לזה מה שאמור למטה (פסוק כז) ויבא יעקב אל יצחק אביו ממרא קרית הארבע ואלו היתה רבקה שם היה מזכיר "אל אביו ואל אמו" כי היא השולחת אותו שם והגורמת לו כל הטובה ויצחק בעצתה צוה אותו ללכת שם וכתב רש"י ולפי שהעלימו את יום מותה שלא יקללו אותה הבריות כרס שיצא ממנה עשו אף הכתוב לא פרסמה ומדרש חכמים הוא (פסדר"כ זכור ד) והנה גם מיתת לאה לא יזכיר אבל הכוונה להם מפני שהזכיר המיתה ברמז ותלה הדבר במניקתה וכיון שדבר בה למה הסתיר הענין ולא גלהו וטעם הקללה אינו מחוור שהרי הזכירו במיתת יצחק (להלן פסוק כט) ויקברו אותו עשו ויעקב בניו אבל יתכן לומר שלא היה לה כבוד במיתתה כי יעקב איננו שם ועשו שונא אותה ולא יבא שמה ויצחק כהו עיניו ואיננו יוצא מביתו ולכן לא רצה הכתוב להזכיר שיקברוה בני חת וכענין הזה מצאתי (באלה הדברים רבה בפרשה כי תצא למלחמה) תנחומא תצא ד אמרו אתה מוצא כשמתה רבקה אמרין מאן יפוק קמא אברהם מת יצחק יושב בבית ועיניו כהות יעקב הלך לו לפדן ארם יפוק עשו רשיעא קמא ויימרון ברייתא ליטין בזיא דהא כדין ינקין מה עשו הוציאו מטתה בלילה אמר רבי יוסי בר חנינה לפי שהוציאו מטתה בלילה לא פרשו הכתובים מיתתה אלא מן הצד הדא הוא דכתיב ויקרא שמו אלון בכות שתי בכיות הדא הוא דכתיב וירא אלהים אל יעקב ויברך אותו מה ברכו ברכת אבלים ברכו עד כאן והנה בעבור שהיה עשו יחידי בקבורתה פחדו מן הקללה ולא ראו שיהיה לה לכבוד וזה ענין הרמז והיתה דבורה עם יעקב כי אחרי שבאה עם רבקה שבה לארצה ועתה תבא עם יעקב לראות גברתה או נתעסקה בגדול בני יעקב לכבוד רבקה ולאהבתה והיתה בביתו ויתכן שאינה היא המינקת שנאמר בה (לעיל כד נט) וישלחו את רבקה אחותם ואת מניקתה אבל היתה מינקת אחרת שנשארה בבית לבן ובתואל ועתה יביא אותה יעקב עמו לכלכל את שיבתה לכבוד אמו כי כן דרך הנכבדים להיות להם מיניקות רבות כי רחוק הוא שתהיה הזקנה השליח שתשלח אמו ליעקב כדברי רבי משה הדרשן
@91 **שמך יעקב** . יאמר כי עתה עודך אתה נקרא יעקב אף על פי שהחליף שמך שרו של עשו כי הוא לא נשתלח לך להחליף את שמך אבל מעתה לא יקרא שמך יעקב כי אם ישראל יהיה שמך וזה טעם ויקרא את שמו ישראל או ירמוז שקרא את שמו ישראל מוסף על יעקב לא שיאסר להקרא יעקב
@93 **ואת הארץ אשר נתתי לאברהם וליצחק לך אתננה** . כאשר נתתיה להם כן אתננה לך ירמוז זה לשבועה כי להם נתנה בשבועה שלא יגרום החטא אבל לו נתנה מתחלה בלא שבועה וזהו שאומר בכל מקום (שמות לג א ועוד) אשר נשבעתי לאברהם ליצחק וליעקב או שיהיה הכפל הנבואה לו לשבועה כאשר פירשתי כבר
@94 **ויעל מעליו אלהים** . כמו שאמר באברהם (לעיל יז כב) ויעל אלהים מעל אברהם ובשניהם להודיע כי לא היה זה מראה וחלום נבואה בלבד או כענין ותבא אותי ירושלימה במראות אלהים (יחזקאל ח ג) אבל ששרתה עליו שכינה במקום אשר הוא עומד ועל דרך האמת עלה מעליו אלהים במקום המדבר עמו כענין שנאמר ברוך כבוד ה' ממקומו (שם ג יב) ויאמר מה שהזכירו החכמים האבות הן הן המרכבה (ב"ר פב ו)
@95 **ויצב יעקב מצבה** . פירש רבי אברהם וכבר הציב בפעם הראשונה מצבה ונסך עליה עתה נסך ויצק עליה שמן ונכון הוא
@96 **ויקרא יעקב את שם המקום בית אל** . יקראנו כן פעם אחר פעם להודיע כי הדבר אמת ונכון כי הוא בית אלהים ושם השכינה תמיד וכן ענין שם באר שבע
@97 **כברת ארץ** . מנחם פירש לשון "כביר" מהלך רב ואגדה (ב"ר פב ז) בזמן שהארץ חלולה ככברה שהניר מצוי והסתו עבר ועדיין השרב לא בא ואין זה פשוטו של מקרא שהרי בנעמן מצינו (מלכים ב ה יט) וילך מאתו כברת ארץ ואומר אני שהוא שם מדת קרקע לשון רש"י והנכון מה שחשב בו ר' דוד קמחי כי הכ"ף לדמיון ואיננה שרשית ומוצא המלה היו לברות למו (איכה ד י) ותברני לחם ( יג ה) ענין אכילה מועטת בבקר ופירושה שיעור מהלך ארץ מן הבקר עד לעת האוכל כי כן ישערו כל הולכי דרך זה כתבתי תחילה ועכשיו שזכיתי ובאתי אני לירושלם שבח לאל הטוב והמטיב ראיתי בעיני שאין מן קבורת רחל לבית לחם אפילו מיל והנה הוכחש הפירוש הזה וגם דברי מנחם אבל הוא שם מדת הארץ כדברי רש"י ואין בו תאר רק הסכמה כרוב השמות והכ"ף לשמוש שלא נמדד בכוון ואם יהיה השם הזה מתואר יתכן שיהיה ברת כמו בת מלשון מה ברי ומה בר בטני (משלי לא ב) והוא שם למדה הקטנה שימדדו הולכי ארחות כמו למיל היום ויאמר לה "בת ארץ" כי המדה כמו בת לפרסה או למדה אחרת ידועה בימים ההם וכן ראיתי שאין קבורה ברמה ולא קרוב לה אבל הרמה אשר לבנימן רחוק ממנה כארבע פרסאות והרמה אשר בהר אפרים (שמואל א א א) רחוק ממנה יותר משני ימים על כן אני אומר שהכתוב שאומר קול ברמה נשמע (ירמיהו לא יד) מליצה כדרך משל לאמר כי היתה רחל צועקת בקול גדול ומספד מר עד שנשמע הקול למרחוק ברמה שהיא בראש ההר לבנה בנימן כי איננו שם והיא חרבה מהם לא נאמר בכתוב "ברמה רחל מבכה על בניה" אבל אמר כי שם נשמע הקול ונראה בעיני כי קברה יעקב בדרך ולא הכניסה לעיר בית לחם יהודה הקרובה שם לפי שצפה ברוח הקודש שבית לחם אפרתה יהיה ליהודה ולא רצה לקברה רק בגבול בנה בנימן והדרך אשר המצבה בה קרובה לבית אל בגבול בנימין וכך אמרו בספרי (זאת הברכה לג יא) בחלקו של בנימין מתה כדאיתא בפרשת וזאת הברכה וראיתי ליונתן בן עוזיאל שהוא מרגיש בזה ואמר קל ברום עלמא אשתמע ותרגם כל הכתוב על כנסת ישראל
@99 **בן אוני** . בן צערי בנימין נראה בעיני לפי שהוא לבדו נולד בארץ כנען שהוא בנגב כשאדם בא מארם נהרים כמו שאמר בנגב בארץ כנען (במדבר לג מ) הלוך ונסוע הנגבה (לעיל יב ט) בנימין בן ימין לשון צפון וימין אתה בראתם (תהלים פט יג) ולפיכך הוא מלא לשון רש"י ולא הבינותי זה שתהא ארץ ישראל דרומית לארם נהרים שהרי ארם מזרחית לארץ ישראל כדכתיב (לעיל כט א) וילך ארצה בני קדם וכתיב (במדבר כג ז) מן ארם ינחני בלק מלך מואב מהררי קדם ויעקב עבר הירדן שהוא למזרחה של ארץ ישראל והיה חוזר דרך אדום שהוא בדרום ארץ ישראל נמצא ארם מזרחית דרומית לארץ ישראל וארץ ישראל לצפונה אבל אם נולד בתחום בית לחם אפרתה שהוא בארץ יהודה כדכתיב (שופטים יט ב) בית לחם יהודה וכתיב (מיכה ה א) ואתה בית לחם אפרתה צעיר להיות באלפי יהודה הנה הוא בדרומה של ארץ ישראל והנה בין בית אל ובין בית לחם אפרת נולד ואם המקום בהר אפרים הרי הוא בצפונה של ארץ ישראל כדכתיב (יהושע יח ה) יהודה יעמוד על גבולו מנגב ובית יוסף יעמדו על גבולם מצפון ואם בחלקו של בנימין גם כן אינה בדרום דכתיב ויהי להם גבול לפאת צפונה ומכל מקום אין טעם לקרותו בן דרום והנכון בעיני כי אמו קראתו בן אוני ורצתה לומר בן אבלי מלחם אונים (הושע ט ד) לא אכלתי באוני (דברים כו יד) ואביו עשה מן אוני כחי מלשון ראשית אוני (להלן מט ג) ולאין אונים (ישעיהו מ כט) ולכן קרא אותו בנימין בן הכח או בן החוזק כי הימין בו הגבורה וההצלחה כענין שכתוב (קהלת י ב) לב חכם לימינו ימינך תמצא לכל שונאיך (תהלים כא ט) ימין ה' רוממה (שם קיח טז) רצה להיות קורא אותו בשם שקראתו אמו כי כן כל בניו בשם שקראו אותם אמותם יקראו והנה תרגם אותו לטובה ולגבורה וראיתי בבראשית רבה (פב ט) בן אוני בן צערי ואביו קרא לו בנימין בלשון הקדש ולא ידעתי מהו כי הכל לשון הקדש וכן שם כל בניו לשון קדש הוא אבל רמזו למה שאמרתי שתרגם הלשון לטובה
@103 **וישמע ישראל** . סיפר הכתוב ענותנותו כי שמע בחלל בנו יצועיו ולא צוה שיוציאוהו מביתו מכלל בניו ולא ינחל עמהם אבל ימנה עמהם ויהיו שנים עשר והוא ימנה ראשון ולכך עשה משתי הפרשיות פסוק אחד כי אף על פי שהוא תחלת ענין שבא למנות השבטים משנולדו כולם רמז כי ראובן לא נדחה במעשהו ועל דרך הפשט יתכן שבלבל ראובן יצועי בלהה מפחדו שלא תלד ליעקב עוד כי הוא הבכור וחשב לקחת שני חלקים ויפסיד יותר מכל האחים ולא פחד מאמו כי זקנה היתה ואולי מתה זלפה או חשש לכבוד אמו בעבור היותה שפחתה ולכן נטלה ממנו הבכורה מדה כנגד מדה וזהו טעם ויהיו בני יעקב שנים עשר כי לא הוליד אחרי כן
@109 **ויהיו ימי יצחק** . אין מוקדם ומאוחר בתורה מכירתו של יוסף קדמה למיתתו של יצחק לשון רש"י וכבר כתבתי (לעיל יא לב) שזה מנהג הכתוב בכל הדורות יספר ענין האדם ותולדותיו ומיתתו ויתחיל בתולדות הדור האחר וראוי היה להקדים מיתת יצחק לתולדות יעקב כאשר עשה באברהם ובכל דורות הראשונים אבל יתכון הכתוב להגיד כי יצחק מת בשיבה טובה זקן ושבע ימים אחרי ששב אליו בנו המבורך הנוחל מעלתו וקברוהו בכבוד עשו ויעקב בניו גדולי העולם ולא הוצרך להזכיר כי קברוהו במערת המכפלה בעבור שהזכיר כי היה בעיר ההיא ואנה יקברוהו רק בקבר אביו
@112 **עדה בת אילון** . היא בשמת בת אילון ונקראת בשמת (לעיל כו לד) על שם שהיתה מקטרת בשמים לעבודה זרה ואהליבמה היא יהודית אותו רשע כינה שמה יהודית לומר שהיא כופרת בעבודה זרה כדי להטעות את אביו בשמת בת ישמעאל ולהלן הוא קורא לה מחלת (לעיל כח ט) מצאתי בהגדת מדרש ספר שמואל (פרק יז) שלשה מוחלין להם על כל עונותיהם גר שנתגייר והעולה לגדולה והנושא אשה ולמד הטעם מכאן לכך נקראת מחלת שנמחלו לו עונותיו כל זה לשון רש"י והנה לא נתן טעם באבי אהליבמה שנקרא שם בארי וכאן ענה ובשמת בת ישמעאל יהיה שם העצם והוא שם תואר לקטור הבשמים ובבראשית רבה (סז יג) אמרו נתן עשו דעתו להתגייר מחלת שמחל לו הקב"ה על עונותיו בשמת שנתבשמה דעתו עליו והנה שניהם תאר אין שם העצם נודע בם ולכך אמר רבי אברהם כי היו לה שני שמות וגם לאביה ויתכן לומר כי השתים נשים ההם מתו בלא בנים אולי נענשו בעבור שהיו מורת רוח ליצחק ולרבקה ונשא אחות אשתו בת אלון ואחרת אהליבמה בת ענה אבל בת ישמעאל אחות נביות בעבור שהיה לה שם כעור בלשון הקדש מחלת קרא את שמה בשם הנכבד אשר היה לאשתו הראשונה מלשון בשמים כי היתה חביבה עליו בעבור שהיתה ממשפחתו ואיננה רעה בעיני יצחק אביו
@116 **ויקח עשו את נשיו ואת בניו ואת בנותיו** . זה המסע היה אחרי שוב אחיו מחרן והאחזו בארץ כנען כמו שאמר כאן ואפשר שהיה גם אחרי מות אביהם והנה בעוד אחיו בחרן היה עשו בשעיר ככתוב למעלה (לב ד) אבל הענין כי עשו הלך לשעיר בימי אלופי החרי יושבי הארץ ויהי לשר הולך עם ד' מאות איש ובניו וביתו היו בארץ כנען ויתכן שהיתה לו שם אחוזה במקום אחד במישור לא בהר שעיר על כן ייחס לו ארצה שעיר שדה אדום ואחרי שחזר אחיו לארץ כנען פנה לו מפניו כי ידע שארץ כנען נחלת אחיו אשר נתן לו אביו בברכתו ולקח בניו וכל נפשות ביתו עם רב והלך לשעיר להתיישב שם ואז נלחם בבני שעיר החרי יושבי הארץ כי אולי פחדו ממנו ולא היו נותנים אותו לבא בגבולם בהר שעיר שהיו שם המבצרים אלא שישב בשדה אדום במקומו הראשון וישמידם ה' מפניהם ויירשום וישבו תחתם כאמור במשנה תורה (דברים ב כא) ולכך יאמר שם (ב ה) כי ירושה לעשו נתתי את "הר" שעיר וטעם וילך אל ארץ אמר אונקלוס אל ארץ אחרת ורש"י פירש לגור באשר ימצא כי הלך אל ארץ אשר ימצא לו מקום לחנותו עד שבא אל הר שעיר וישב שם והנכון בעיני שיאמר וילך אל ארץ שעיר וחסרו הכינוי בעבור היותו מובן שכבר הזכיר (לעיל לב ד) שהיה עומד בארץ שעיר והידוע כי לשם יוליך ביתו ויזכיר בסמוך (פסוק ח) וישב עשו בהר שעיר ונמצא כזה (מלכים א טז יח) ויבא אל ארמון בית המלך וישרף עליו את בית מלך ושיעורו בית המלך הזה שהיה בו וכן וישרף את הבמה הדק לעפר ושרף אשרה (מלכים ב כג טו) כלומר אשר לירבעם הנזכרת במקום ההוא וכן ויאמר יואב לכושי לך הגד למלך וישתחו כושי ליואב ( יח כא) וחמור והאריה (מלכים א יג כח) וכן כי נשברו אניות בעציון גבר (שם כב מט) האניות וכן רבים אף כאן וילך אל ארץ כמו אל הארץ ארץ שעיר הנזכרת
@117 **ולא יכלה ארץ מגוריהם** . טעמו עיר מגוריהם היא חברון אשר גר שם אברהם ויצחק כי ארץ כנען תשא כזה וכזה אלף פעמים אבל עשו בראותו כי לא יוכל לעמוד בעירו ובמקומו עזב את כל הארץ לאחיו והלך לו
@119 **ואלה תולדות עשו אבי אדום** . בא להזכיר התולדות אשר הולידו בניו אחרי שהלכו עמו לשעיר כי הוא לא הוליד שם והנה החל ממנו לומר הוא הוליד את אליפז ורעואל והם הולידו בארץ שעיר תולדות הללו ויזכיר עמהם בני אהליבמה הנולדים בארץ כנען אף על פי שלא הזכיר להם תולדות בארץ שעיר כדי שימנו עם אחיהם בני עשו הנזכרים בתחילת הפרשה ועוד בעבור היותם בשעיר אלופים כי כל אלופיהם יזכיר
@122 **ותמנע היתה פילגש** . מפני שלא הקפיד בכל האחרים להודיע שם האם דרשו רבותינו (ב"ר פב יד) כי זה להודיע גדולתו של אברהם אבינו כמה היו תאבים להדבק בזרעו שהרי תמנע זו בת אלופים היתה שנאמר ואחות לוטן תמנע אמרה איני זוכה להנשא לך הלואי ואהיה פילגש כמו שכתב רש"י ויתכן כי בני אליפז החמשה היו ידועים לו כי הולידם מנשיו ועמלק בעבור היותו בן פלגש לא היה לו שם באחיו והיה נכלל עם בני עשו בעבור היותו מזרעו והוצרך הכתוב לומר כי אמו פלונית אשר הוא נודע לה ילדתו לאליפז אבל איננו בכלל בני עשו ולא יושב עמהם בהר שעיר כי בבני הגבירות יקרא לו זרע ולא בבן הפילגש כי לא יירש בן אמה עם בניו כמו שעשה אביו והנה אנחנו נצטוינו בבני עשו שלא נתעב אותם (דברים כג ח) ולא נקח את ארצם (שם ב ה) והם כל בניו הידועים לו היושבים בשעיר כי הם הנקראים אדום על שמו אבל בן הפילגש אינו בכלל בני עשו ולא עמהם בארצם ונצטוינו בו בהפך לתעב אותו ולמחות את שמו וכתב רש"י עוד ובדברי הימים (א א לו) מונה תמנע בבניו של אליפז מלמד שבא על אשתו של שעיר החורי ויצאה תמנע מביניהם וכשגדלה היתה פילגשו וזהו ואחות לוטן תמנע (להלן פסוק כב) ולא מנאה מבני שעיר שהיתה אחותו מן האם ולא מן האב ואין דעתי סובלת זה כי היה ראוי לומר בדברי הימים "ותמנע בתו" ולמה ימנה האשה בבנים אולי לא יקפיד הכתוב בכך בדבר הידוע כי מצינו שם בדברי הימים (א ה כט) ובני עמרם אהרן ומשה ומרים ובני אהרן נדב ואביהוא וגומר ואם כן ראוי שנאמר כי תמנע זאת היא בת אליפז אשר ילדה לו אשת שעיר החורי אחרי מות אישה והיתה אחות לוטן מן האם ונשאה אליפז לפילגש שהעכו"ם מותר בבתו או נאמר על דעת רבותינו כי תמנע הנזכר בדברי הימים הוא תמנע האלוף הנזכר למטה (בפסוק מ) שנמנה שם מבני אליפז כאשר נמנה קרח והוא בן אהליבמה כי שניהם היו ממזרים נולדו מאחד ונמנים עם בני האחר כי רחוק שימנה האשה בין הבנים בתוכם ועל דרך הפשט יש לחשוב בו כי תמנע פילגש אליפז אחרי לידתה את עמלק ילדה בן ותקש בלדתה ותמת ותקרא את שמו תמנע בעבור הזכיר שמה ואביו אליפז קרא לו קרח ולא הזכיר הכתוב הבן הזה לתמנע אמו כדי שלא יאריך כי הכונה היתה למנות עמלק בפני עצמו אבל בני אליפז שבעה היו ומנה הכתוב האלופים דרך מעלתם על כן הקדים קנז וקרח לגעתם ואני עוד סובר בכתוב הזה מה שאמרו רבותינו בשלשים ושתים מדות (מדה יא) שהאגדה נדרשת אמרו סדור היה ראוי להיות אלא שנחלק שנאמר (דהי"ב ל יח) כי מרבית העם וכו' וגם רודפי הפשט יאמרו כן בפסוקים אחרים וכן זה יאמר בני אליפז תימן אומר צפו וגעתם וקנז ותמנע וחזר ואמר היתה פילגש לאליפז בן עשו ותלד לאליפז את עמלק ולא הזכיר שם הפילגש והאמת שהיא אחות לוטן תמנע והיא הסבה שלא הזכיר שמה כי לא רצה לאמר שני פעמים ותמנע לזכר ולנקבה והנה בני אליפז שבעה והם האלופים הנזכרים לו אבל החליפו שם זה הקטן בעבור היות שמו כשם הפילגש שלא יחשב כבנה וקראוהו קרח בעלותו למעלת אלוף ורבי אברהם אמר כי קרח בן אהליבמה אשת עשו הוא נמנה פעמים כי הוא הקטן מבני אהליבמה וגדלתו עדה וכן בני מיכל בת שאול כדברי רבותינו (סנהדרין יט) ועל דעת הזו יהיה פירוש הכתוב בדברי הימים כי תמנע ילדה עמלק שיהיה שיעורו ולתמנע עמלק וחסרו הלמ"ד כדרך ושני שרי גדודים היו בן שאול ( ד ב) לבן שאול והנכון מה שחשבתי בו וטעם אלה בני עדה על הרוב כי עמלק איננו בנה וכן אלה בני יעקב אשר ילד לו בפדן ארם (לעיל לה כו) אינו על בנימין
@130 **אלה בני שעיר החרי** . החרי שם איש היה אבי אומה קדמונית תקרא על שמו כמו האמורי והפריזי כמו שנאמר (דברים ב כב) אשר השמיד את החורי מפניהם ונקרא שעיר על שם הארץ שנקראת שעיר והשם הזה היה לארץ מן עשו שהוא איש שעיר מיום שהלך שם ואילך וכן שם אדום ממנו היה אבל הכתוב הפריש ביניהם כי אלה הם בני שעיר החורי שהיו יושבי הארץ למבראשונה לא בני שעיר האדומי אשר בא שם ועוד אפרש יחוס החורי במשנה תורה (דברים ב י) בעזרת השם וכתב רבי אברהם הזכיר הכתוב זה להפריש יחוסי שעיר ועשו כי ישראל יצוו על בני עשו ורש"י כתב (בפסוק כד) לא הוזקק לכתוב משפחות החורי אלא מפני תמנע להודיע גדולת אברהם
@132 **ואחות לוטן תמנע** . כמו ואחות תובל קין נעמה (לעיל ד כב) ואחיותיהם צרויה ואביגיל (דהי"א ב טז) ותמר אחותם (שם ג ט) וסרח אחותם (להלן מו יז) כי המנהג ליחס הבת אל האחים והיה ראוי שתמנה למעלה עם בני שעיר ודישון ואצר ודישן ותמנע אחותם אבל היתה אחות לוטן בת אביו ובת אמו לא אחות שאר האחים ולכן רצה ליחס אותה אליו או שהיתה אחותו מן האם ולא מן האב ואיננה בת שעיר החורי
@134 **ואלה בני צבעון ואיה וענה** . הוי"ו יתירה וכן עבד אביך ואני מאז ועתה ואני עבדך ( טו לד) דין שניהם אני ואלה ראשי בית אבותם ועפר וישעי (דהי"א ה כד) וכמוהם רבים והנה צבעון זה הוא הבן השלישי לשעיר החורי והוליד שני בנים אלו איה וענה וסיפר הכתוב כי ענה זה בן צבעון הוא אותו ענה שמצא הימים במדבר ברעותו החמורים של צבעון אביו להבדיל בינו ובין ענה דודו אחי צבעון אביו וזה ענה בן צבעון הוא חמיו של עשו
@134 "אשר מצא את הימים" - כדעת מקצת רבותינו בתלמוד (פסחים נד) הם הפרדים וזה האיש מצא כי יולידו מין שלא במינו ואין כן בשאר מיני הכלאים ואמר במדבר ברעותו החמורים כי היו לו שם במדבר חמורים רבים תובעים אתונות והרביעם עם הסוסיות והולידו ונראה שנחשב לו בדורו לחכמה כי הכיר במיניהם שהם קרובים בטבע ויולידו והיה נודע במעשה ההוא ועל כן יתארהו בו ואונקלוס תרגם גבריא והנראה מסברתו כי ענה זה באו עליו מן האומה הנקראת אימים לפנים עם גדול ורם כענקים (דברים ב י) ורצו לגזול ממנו החמורים של צבעון אביו והוא היה במדבר ואין עוזר לו ותמצא ידו להם והציל מידם והוא מלשון תמצא ידך לכל אויביך (תהלים כא ט) ולא המציתך ביד (שאול) דוד ( ג ח) או יאמר שמצא אותם ונצל והיה נודע בגבורה הזאת ונכון הוא
@135 **ואלה בני ענה דישון ואהליבמה בת ענה** . דרך הכתוב לאמר בבנות כן כמו ואת דינה בתו (להלן מו טו) וזה ענה הוא הבן הרביעי לשעיר החורי אחי צבעון הנמנה אחריו למעלה (בפסוק כ) כי הפרשה תמנה שבעה בני שעיר החורי כתולדותם והיה לזה ענה בן אחד יקרא גם כן דישון כשם דודו ולו בת תקרא אהליבמה כשם קרובתה בת ענה בן צבעון ולכך יאמר הכתוב באשת עשו (לעיל פסוק ב) אהליבמה בת ענה בת צבעון להגיד כי היא בת ענה שמצא הימים נכדת צבעון לא אהליבמה בת ענה בן שעיר החורי אחי צבעון ועל דעת קצת רבותינו (פסחים נד) אין בפרשה רק איש אחד הנקרא ענה והוא בן צבעון שבא בזנות על אמו אשת שעיר החורי וימנה אותו הכתוב (בפסוק כ) בבני שעיר החורי כי יחשבוהו האנשים כבנו ויקראוהו ענה בן שעיר וגדלו בין בניו בחשבו שהוא בנו וימנה אותו הכתוב פעם אחרת (בפסוק כד) על פי האמת בן לצבעון וזה מדרשם של דורשי חומרות כמו שמוזכר במסכת פסחים (שם) ואיננו דברי הכל בגמרא ולא משמעו של מקרא כלל
@136 **ואלה בני דישן חמדן ואשבן** . הוא דישון הבן החמישי לשעיר כי אין קפידא שיקראנו דישן או דישון רק כשהם בפסוק אחד להבדיל בין שניהם וכן ויעש חירום את הכיורות ויכל חירם (מלכים א ז מ) והוצרך הכתוב בכאן לקראו דישן שלא יחשב שהוא דישון בן ענה הנזכר בסמוך ליחס לו תולדות כי כן יהיה במשמע
@141 **ואלה המלכים אשר מלכו בארץ אדום** . נכתב זה להגיד כי נתקימה בו ברכת יצחק שאמר לו ועל חרבך תחיה (לעיל כז מ) כי גברו על בני שעיר החורי ומלכו עליהם בארצם ואלה הערים מדינות בארץ אדום כי בצרה לאדום היא כמו שכתוב (ישעיהו לד ו) כי זבח לה' בבצרה וטבח גדול בארץ אדום וכן ארץ התימני מאדום כמו שנאמר בו (עובדיה א ט) וחתו גבוריך תימן למען יכרת איש מהר עשו וכולם כך המה אבל ספר הכתוב כי לא היו מלך בן מלך כאשר היו בישראל
@141 "ולפני מלך מלך" - ימים רבים קודם ואין טעם "לפני מלך מלך" שנמשכה מלכות אלה עד מלכות ישראל (ראה רש"י ורד"ק) אבל לאמר כי אז לא תהיה להם מלכות לקיים "ואת אחיך תעבוד" (לעיל כז מ) ויתכן שאלו כולם בימי משה כבר עברו כי היו זקנים בעת שהמליכו אותם ולא האריכו ימים
@145 **וטעם המכה את מדין בשדה מואב** . להגיד גבורתו שבאו המדינים בשדה מואב להשגב עמם ונצח את כלם
@148 **ובעל חנן בן עכבור** . היה ממקום שאול על כן לא הזכיר לו עיר אחרת ויתכן שהיה חנן מקום והוא בעל עליו ואחרי כן מלך
@150 **ואלה שמות אלופי עשו** . מתחלה (פסוקים טו-יט) מנה בני בניו שהיו אלופים בדור ההוא ואחר כן הצליחו מזרעו למלוכה ואחרי כן פסקה מלכותם וחזרו ונתנו את אלו אלופים לראש וכך נאמר בדברי הימים (א א נא) וימת הדד ויהיו אלופי אדום אלוף תמנע כך פירש רש"י ומה שאמר למשפחותם למקומותם בשמותם למושבותם בארץ אחוזתם (פסוק מג) כי הראשונים היו כל האחים אלופים יושבים כלם בעיר אחת מושלים בעם כאחד או כענין נשיאי שבט וראשי בתי אבות אבל אלו אחרונים היו אלופים למשפחותם כי כל אחד היה אלוף לכל משפחות בני עשו ובכל מקומות מושבותם והוא לבדו נקרא בדור אלוף אין אחר נקרא כן בכל ארץ אחוזתם כי היו כמלכים לארצם אבל לא ישבו לכסא להם ולא נתנו עליהם הוד מלכות ונכתבה הפרשה בדרך הנבואה לדעת רבים (רש"י וראב"ע והרד"ק) ואיננו נכון כי הנבואה למה תזכיר את אלה ועד איזה זמן תמנה ותפסיק בהם אבל הנכון שכל אלה לפני התורה ונאמר שמשלו כאחד ויהיה פירוש למקומותם שמשל כל אחד במקומו או שהיה ממשלתם זמן מועט ושנות רשעים תקצורנה (משלי י כז)
@153 **מגדיאל** . זו רומי לשון רש"י ולא הבינותי זה כי אם נאמר שיהיה נבואה לימים רבים ולעתים רחוקות הנה מלכים רבים מלכו לאדום על מלכות רומי ואין רומי אלוף אבל היא מלכות גדולה ואמתני ותקיפא יתירה לא היה כמוה בממלכות אבל מה שאמרו בפרקי רבי אליעזר (לח) בשכר שפינה את כליו מפני יעקב אחיו נתן לו מאה מדינות משעיר ועד מגדיאל ומגדיאל זו רומי שנאמר אלוף מגדיאל אלוף עירם כוונתם בזה מה שהודעתיך כמה פעמים כי היו המקרים בראשונים רמז לזרעם והנה אלה האלופים האחרונים עשרה עם מגדיאל רמז שיהיו מלכי אדום בממשלתם במלכות הרביעית עשרה ימלכו על ארץ אדום והעשירי מהם ימלוך על רומי ומשם תתפשט אחרי כן מלכותם על כל העולם ולזה ירמוז שם מגדיאל שיתגדל על כל אל כמו שאמר בו (דניאל יא לו) ועשה כרצונו המלך ויתרומם ויתגדל על כל אל וזהו שנאמר (שם ז כד) וקרניא עשר מינה מלכותא עשרה מלכין יקומון ואחרן יקום אחריהון והוא ישנא מן קדמיא ואמרו בבראשית רבה (עו ו) כלם ביוצאי ירכו של עשו הכתוב מדבר ודרשו (שם פג ד) אלוף עירם שהוא עתיד לערום תיסוריות למלך המשיח במהרה יגלה חסלת פרשת וישלח
